INSERT INTO game_config_skills VALUES('stealth','Skradanie','DEX',5,1,'2026-04-14T00:00:00Z','Ciche poruszanie się i unikanie wykrycia. Odpowiada za wymykanie się, skradanie i działanie w cieniu.','skradam przekradam skrytobieżnie skrycie cicho przemykam zakradam');
INSERT INTO game_config_skills VALUES('athletics','Atletyka','STR',5,2,'2026-04-14T00:00:00Z','Wysiłek fizyczny: bieganie, skoki, wspinaczka i dźwiganie.','wspinamy wspinasz wspinac wdrapuje wdrapac skacze przeskakuje przeskoczyc skakac biegne biegamy sprint');
INSERT INTO game_config_skills VALUES('initiative','Inicjatywa','DEX',5,3,'2026-04-14T00:00:00Z','Szybka reakcja i gotowość do działania. Odpowiada za tempo i pierwszeństwo w niebezpiecznych chwilach.','');
INSERT INTO game_config_skills VALUES('attack','Atak','STR',5,4,'2026-04-14T00:00:00Z','Zdolność do skutecznego uderzenia: celowanie, siła i timing ataku.',NULL);
INSERT INTO game_config_skills VALUES('awareness','Spostrzegawczość','WIS',5,5,'2026-04-14T00:00:00Z','Wnikliwa obserwacja i czujność. Pomaga dostrzec zagrożenia, śledzić tropy i wyłapać drobne sygnały.','rozgladam nasłuchuję zauważam spostrzegam wypatruję rozglądam przeszukuję obserwuję');
INSERT INTO game_config_skills VALUES('two_handed','Broń dwuręczna','STR',5,5,'2026-04-14T00:00:00Z','Biegłość w prowadzeniu ciężkiej broni dwuręcznej bez utraty kontroli nad ciosem.',NULL);
INSERT INTO game_config_skills VALUES('persuasion','Perswazja','CHA',5,6,'2026-04-14T00:00:00Z','Urok, argumenty i przekonywanie innych. Odpowiada za perswazję i rozmowę prowadzącą do zgody.','przekonuję proszę negocjuję dyplomat tłumaczę proszę kłaniam');
INSERT INTO game_config_skills VALUES('intimidation','Zastraszanie','CHA',5,7,'2026-04-14T00:00:00Z','Straszenie, stanowczość i presja psychiczna. Odpowiada za zastraszanie i wymuszanie reakcji.','grożę zastraszam straszę grozę przemocą wymuszam');
INSERT INTO game_config_skills VALUES('survival','Przetrwanie','WIS',5,8,'2026-04-14T00:00:00Z','Przetrwanie w trudnych warunkach. Odpowiada za orientację, instynkt i decyzje w terenie.','przetrwanie orient tropię ognisko schronienie dzikie');
INSERT INTO game_config_skills VALUES('lore','Wiedza','INT',5,9,'2026-04-14T00:00:00Z','Wiedza z opowieści i dawnych ksiąg. Odpowiada za rozpoznanie kultury, historii, symboli i opowieści świata.','historia wiedza kronik legend mit podanie opowieść uczony');
INSERT INTO game_config_skills VALUES('arcana','Arkana','INT',5,10,'2026-04-14T00:00:00Z','Rozumienie magii i zjawisk magicznych. Odpowiada za rozpoznawanie zaklęć, rytuałów i sekretów arkanów.','zaklęcie arkana magia rozszyfrowuję odczytuję wypisuję rytuał mistyczny zaklęcia');
INSERT INTO game_config_skills VALUES('medicine','Medycyna','WIS',5,11,'2026-04-14T00:00:00Z','Udzielanie pomocy i leczenie. Odpowiada za ocenę ran, dobór środków i stabilizację w walce.','opatrzyć opatrunek bandażuję bandażuje');
INSERT INTO game_config_skills VALUES('investigation','Dochodzenie','INT',5,12,'2026-04-14T00:00:00Z','Dociekliwość i analizowanie szczegółów. Odpowiada za szukanie tropów, wyciąganie wniosków i składanie faktów.','badam przeszukuję dochodzę śledczę analizuję sprawdzam tropię ślady');
INSERT INTO game_config_skills VALUES('lockpick','Otwieranie zamków','DEX',5,14,'2026-04-14T00:00:00Z','Otwieranie zamków bez klucza — wytrychem, improwizowanym narzędziem lub gołymi rękami.','wytrych sforsować wytrychem wytrychami');
INSERT INTO game_config_skills VALUES('acrobatics','Akrobatyka','DEX',5,15,'2026-04-14T00:00:00Z','Zwinność i równowaga w ruchu — przewroty, balansowanie na krawędzi, łapanie się w upadku.','salto przewrót akrobacj balansuję balansować');
INSERT INTO game_config_skills VALUES('insight','Wnikliwość','WIS',5,16,'2026-04-14T00:00:00Z','Czytanie intencji i emocji rozmówcy — wykrywanie kłamstwa, oceny czyichś motywów.','wyczytać intencj przejrzeć podstęp zamiarów');
INSERT INTO game_config_skills VALUES('deception','Oszustwo','CHA',5,17,'2026-04-14T00:00:00Z','Wprowadzanie w błąd słowem lub gestem — kłamanie, blefowanie, granie roli.','blefuję udaję oszukać ściemniam kłamię');
