INSERT INTO game_config_meta VALUES('slash_commands_ui','[{"command": "/help", "alias": "", "description": "Show this list of available commands", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/sheet", "alias": "", "description": "Display your full character sheet", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/roll", "alias": "", "description": "Roll d20 + modifier for the last GM-requested roll", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/name <new name>", "alias": "", "description": "Rename your character", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/history", "alias": "", "description": "Show the last 10 turns of the session", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/atak", "alias": "", "description": "Stan aktywnej walki (wrogowie, HP, czyja tura) albo informacja, że walka nie trwa", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/mem [pytanie]", "alias": "", "description": "Pytanie o przeszłość z podsumowań — bez wpływu na narrację (żółte dymki)", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/helpme [pytanie]", "alias": "", "description": "Doradca OOC — wskazówki bez zmiany fabuły (czerwone dymki); nie wpływa na kontekst narracji", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/whisper <imię> <wiadomość>", "alias": "/szept", "description": "Szept do gracza — widoczny tylko dla nadawcy i odbiorcy (tylko multiplayer)", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/export", "alias": "", "description": "Export the full session to a text file on the server (/data/exports/)", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/quest", "alias": "/zadania", "description": "Lista aktywnych zadań (questów) z krótkim opisem", "admin_enabled": true, "player_enabled": true, "enabled": true}, {"command": "/admin", "alias": "", "description": "Komendy admina: add | set | remove | clear | combat | quest | show", "admin_enabled": true, "player_enabled": false, "enabled": false}, {"command": "/debug", "alias": "", "description": "Debug: dump-state | set-hp N | set-state STATE | reset-cooldowns | roll SKILL", "admin_enabled": true, "player_enabled": false, "enabled": false}, {"command": "/search", "alias": "", "description": "Przeszukaj zabitą postać lub lokację", "admin_enabled": true, "player_enabled": true, "enabled": true}]','1970-01-01T00:00:00Z');
