INSERT INTO game_config_enemies VALUES('town_guard_corrupt','Skorumpowany Strażnik',14,14,2,'d6','Strażnik miejski, który dawno zapomniał o honorze. Pracuje dla tego, kto więcej zapłaci.',1,NULL,'2026-04-20 19:37:52','2026-04-22 12:08:33','weak',1,1,'physical',18,'[]','loot_city_enforcer','Pracuje dla przestępczej frakcji. Można go przekupić (DC 11 CHA + 5+ gp) lub szantażować.',0.599999999999999977,0,NULL,'permanent',NULL,'standard',0,12,NULL);
INSERT INTO game_config_enemies VALUES('rabble_rioter','Rozjuszony Tłumowicz',6,9,0,'d4','Zwykły mieszczanin popchnięty do przemocy. Niebezpieczny tylko w grupie.',1,NULL,'2026-04-20 19:37:52','2026-04-22 12:08:33','weak',1,0,'physical',6,'[]','loot_rabble_rioter','Groźny tylko w grupie 5+. Pojedynczo: DC 8 WIS save lub ucieka po pierwszym trafieniu.',0.200000000000000011,0,NULL,'permanent',NULL,'standard',0,12,NULL);
