INSERT INTO game_config_enemies VALUES('cult_initiate','Inicjat Kultu',7,10,1,'d4','Nowy wyznawca mrocznego bóstwa. Zna kilka zaklęć, ale brakuje mu odwagi.',1,NULL,'2026-04-20 19:37:52','2026-04-22 12:08:31','weak',1,0,'magic',12,'[]','loot_cult_initiate','Gdy atakuje go kapłan kultu: +2 do morale (nie ucieka przez 3 tury).',0.5,0,NULL,'permanent',NULL,'standard',0,12,NULL);
