INSERT INTO game_config_enemies VALUES('bandit_lieutenant','Zastępca Bandytów',22,13,3,'d8','Doświadczony zbój dowodzący małą grupą rozbójników. Taktyczny i bezwzględny.',1,NULL,'2026-04-20 19:37:53','2026-04-23 09:20:37','standard',1,2,'physical',40,'[]','loot_bandit_lieutenant','Dowodzi bandytami — pobliskie bandy mają +1 do moral (nie uciekają). Pokonanie go kończy walkę grupową.',0.699999999999999955,0,NULL,'permanent',NULL,'standard',0,12,NULL);
