INSERT INTO game_config_enemies VALUES('hedge_witch','Wiedźma z Ostępu',16,11,4,'d6','Pustelnica władająca dzikimi zaklęciami. Jej klątwy są nieprzewidywalne i groźne.',1,NULL,'2026-04-20 19:37:53','2026-04-22 12:08:32','standard',1,0,'magic',42,'[]','loot_hedge_witch','Co 2 tury rzuca losową klątwę: -2 STR / -2 DEX / DC 12 WIS save lub confused na 1 turę.',0.800000000000000044,0,NULL,'permanent',NULL,'standard',0,12,NULL);
