INSERT INTO game_config_enemies VALUES('arena_fighter','Gladiator Areny',30,14,5,'d8','Były gladiator, który przeżył setki walk. Każdy jego cios to wyuczona precyzja.',1,NULL,'2026-04-20 19:37:53','2026-04-22 12:08:31','standard',1,3,'physical',55,'[]','loot_arena_fighter','Jeśli HP < 30%: wykonuje Atak Furii — dodatkowy atak bonusowy bez kosztu akcji.',0.599999999999999977,0,NULL,'permanent',NULL,'standard',0,12,NULL);
