INSERT INTO game_config_enemies VALUES('warlord','Watażka',50,16,6,'d10','Przywódca bandy najemników zahartowany w dziesiątkach bitew. Jego krzyk mobilizuje pobliskich sojuszników.',1,NULL,'2026-04-20 19:37:53','2026-04-22 12:08:34','elite',2,4,'physical',160,'[]','loot_generic_elite','Obecność watażki: pobliskie wrogie jednostki mają +1 do ATK i nie uciekają. Przy jego śmierci: wszyscy wrogowie DC 12 WIS save lub rozbiegają się.',0.900000000000000022,0,NULL,'permanent',NULL,'standard',0,12,NULL);
