INSERT INTO game_config_enemies VALUES('street_beggar','Żebrak Uliczny',4,8,0,'d3','Zdesperowany bezdomny, który sięga po kamień lub kij gdy jest w narożniku. Nie szuka walki — szuka przeżycia.',1,NULL,'2026-04-22 10:33:28','2026-04-22 12:08:33','weak',1,0,'physical',3,'[]','loot_street_beggar','Często ucieka po pierwszym trafieniu (DC 8 WIS save lub flees).',0.100000000000000005,0,NULL,'permanent',NULL,'standard',0,12,NULL);
