INSERT INTO game_config_enemies VALUES('corrupt_guard','Skorumpowany Strażnik',14,13,2,'d6','Strażnik miejski, który dawno zapomniał o honorze. Pracuje dla tego, kto więcej zapłaci — i nie pyta o szczegóły.',1,NULL,'2026-04-22 10:33:31','2026-04-22 12:08:31','standard',1,1,'physical',22,'[]','loot_city_enforcer','Można przekupić w trakcie walki (DC 13 CHA, koszt 10+ gp).',0.599999999999999977,0,NULL,'permanent',NULL,'standard',0,12,NULL);
