INSERT INTO game_config_enemies VALUES('highway_robber','Rozbójnik Drogowy',16,12,3,'d6','Doświadczony bandyta polujący na kupców i podróżnych przy traktach. Zna teren i zawsze ma zaplanowaną ucieczkę.',1,NULL,'2026-04-22 10:33:32','2026-04-22 12:08:32','standard',1,1,'physical',32,'[]','loot_highway_robber','Znajomość terenu: nie można go zaskoczyć w lesie ani przy drodze.',0.650000000000000022,0,NULL,'permanent',NULL,'standard',0,12,NULL);
