INSERT INTO game_config_items VALUES('soft_slippers','Miękkie pantofle','armor','Miękkie pantofle z owczej skóry. Pozwalają poruszać się bezgłośnie po deskach albo kamiennych korytarzach.',6,NULL,1,NULL,'2026-05-23 10:09:26','2026-05-23 10:09:26',NULL,0.299999999999999988,0,NULL,NULL,0,'self',1,0,1,'["rogue", "scholar"]','feet',NULL,1,NULL,NULL,NULL,NULL);
