INSERT INTO game_config_items VALUES('wizard_robe','Szata maga','armor','Ciężka jedwabna szata z wszytymi srebrnymi runami. Nie zatrzymuje miecza, ale pochłania część obrażeń magicznych.',75,NULL,1,NULL,'2026-05-23 10:09:26','2026-05-23 10:09:26',NULL,2.0,1,NULL,NULL,0,'self',1,0,1,'["scholar"]','torso',NULL,1,NULL,NULL,NULL,NULL);
INSERT INTO game_config_items VALUES('rope_hemp','Lina konopna (15m)','gear','Pleciona lina z konopi, długości piętnastu metrów. Niezbędna przy wspinaczce, krępowaniu więźniów i tysiącu innych zastosowań.',1,NULL,1,NULL,'2026-05-23 10:09:26','2026-05-23 10:09:26',NULL,4.5,0,NULL,NULL,0,'self',1,0,1,'["warrior", "rogue", "scholar"]','torso',NULL,1,NULL,NULL,NULL,NULL);
