INSERT INTO game_config_items VALUES('lockpicks','Wytrychy','tool','Zestaw cienkich, hartowanych haczyków w skórzanym etui. W rękach łotrzyka otwierają drzwi szybciej niż prawdziwy klucz.',25,NULL,1,NULL,'2026-05-23 10:09:26','2026-05-23 10:09:26',NULL,0.100000000000000005,0,NULL,NULL,0,'self',1,0,1,'["warrior", "rogue", "scholar"]','torso',NULL,1,NULL,NULL,NULL,NULL);
