INSERT INTO game_config_consumables VALUES('old_vitek_healing_brew','Nalewka Starego Witka','Domowa nalewka z leśnych ziół przygotowana przez Starego Witka. Gorzka jak cholera, ale leczy rany.','heal',NULL,0,'self',0.0,1,10,NULL,1,NULL,'2026-05-28 07:48:37','2026-05-28 07:48:37',0,1,'common',NULL);
INSERT INTO game_config_consumables VALUES('gertruda_strength_stew','Porcja Gulaszu Gertrudy','Sytą porcja mięsnego gulaszu przygotowaną przez Gertrudę. Dodaje siły na kilka godzin.','buff',NULL,0,'self',0.0,1,15,NULL,1,NULL,'2026-05-28 07:48:46','2026-05-28 07:48:46',0,1,'uncommon',NULL);
INSERT INTO game_config_consumables VALUES('linen_bandage_basic','Bandaż z Lnianej Koszuli','Prowizoryczny bandaż zrobiony z podartej lnianej koszuli. Podstawowa opatrunkowa pomoc.','heal',NULL,0,'self',0.0,1,5,NULL,1,NULL,'2026-05-28 07:48:55','2026-05-28 07:48:55',0,1,'common',NULL);
INSERT INTO game_config_consumables VALUES('ironbark_healing_elixir','Eliksir Żelaznej Kory','Destylat z kory żelaznych drzew. Leczy rany, wykorzystując żywotną siłę samego lasu.','heal',NULL,0,'self',0.0,1,25,NULL,1,NULL,'2026-05-28 08:20:05','2026-05-28 08:20:05',0,1,'uncommon',9);
INSERT INTO game_config_consumables VALUES('cursed_root_brew','Wywar z Korzeni Klątwy','Niebezpieczny napoj uwarzony z korzeni zaklętego lasu. Daje nadludzą siłę, ale każde użycie przybliża Cię do szaleństwa.','buff',NULL,0,'self',0.0,1,40,NULL,1,NULL,'2026-05-28 08:20:16','2026-05-28 08:20:16',0,1,'rare',9);
INSERT INTO game_config_consumables VALUES('umbravale_memory_elixir','Eliksir Pamięci Umbravale','Destylat z roślin rosnących w ruinach Umbravale. Leczy rany, ale wywołuje dziwne wizje przeszłości miasta.','heal_hp','2d6',0,'self',0.0,1,35,NULL,1,NULL,'2026-05-28 10:19:11','2026-05-28 10:19:11',0,1,2,11);
INSERT INTO game_config_consumables VALUES('potion_of_silence','Napój Ciszy','Tajemniczy płyn używany przez kult. Wzmacnia zręczność i pozwala poruszać się bez dźwięku przez 3 tury.','buff','1d4',2,'self',0.0,1,50,NULL,1,NULL,'2026-05-28 10:19:22','2026-05-28 10:19:22',0,1,3,11);
INSERT INTO game_config_consumables VALUES('forgotten_library_bandage','Bandaż z Biblioteki Zapomnianych','Stare, ale wciąż sterylne bandaże znalezione w Bibliotece Zapomnianych. Podstawowa pomoc medyczna.','heal_hp','1d4',1,'self',0.0,1,15,NULL,1,NULL,'2026-05-28 10:19:32','2026-05-28 10:19:32',0,1,1,11);
