INSERT INTO game_config_riddles VALUES('riddle_shadow','Podążam za tobą w dzień, znikam w nocy. Czym jestem?','cień','["shadow","twój cień","mój cień"]','["Jestem czarny","Znikam gdy nie ma słońca","To twój..."]',1,'general',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_echo','Mówię wszystko co powiesz, a nie mam ust. Czym jestem?','echo','["głos","echo głosu"]','["Mieszkam w górach i jaskiniach","Powtarzam twoje słowa","Nie mam ciała"]',1,'dungeon',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_fire','Jem i rosnę, ale woda mnie zabija. Czym jestem?','ogień','["płomień","fire","żar"]','["Świecę w ciemności","Potrzebuję drewna","Gasisz mnie wodą"]',1,'dungeon',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_time','Stale idę naprzód, nie można mnie cofnąć. Czym jestem?','czas','["upływ czasu","godziny","wieczność"]','["Wszystko niszczę","Królowie się mnie boją","Nie mam początku ani końca"]',2,'magic',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_key','Mam zęby, ale nie gryzę. Czym jestem?','klucz','["klucz do drzwi","zamkowy klucz"]','["Otwieram zamki","Noszę mnie przy pasie","Bez mnie drzwi pozostają zamknięte"]',1,'dungeon',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_death','Bogaci go pragną, biedni go mają, a zniszczy tego kto je spożyje. Czym jestem?','nic','["nicość","pustka","zero"]','["Bogaci chcą więcej tego czego nie mają","Biedni nic nie mają","Jeśli to zjesz..."]',3,'death',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_river','Zawsze biegnę, a nóg nie mam. Czym jestem?','rzeka','["woda","strumień","potok"]','["Mam brzegi","Płynę do morza","Możesz mnie przepłynąć"]',1,'nature',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_mirror','Pokazuję twarz, ale nią nie jestem. Czym jestem?','lustro','["zwierciadło","odbicie"]','["Odbijam światło","Znajdziesz mnie w komnacie","Odwracam lewo i prawo"]',2,'magic',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_book','Mam wiele historii, lecz ust nie mam. Czym jestem?','księga','["książka","tom","pergamin","pismo"]','["Mam strony","Możesz mnie czytać","Noszę wiedzę"]',1,'magic',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_night','Im więcej mnie zabierasz, tym większy się staję. Czym jestem?','dół','["dziura","jama","wykop"]','["Kopiesz mnie w ziemi","Chowasz mnie w ziemi","Wyrasta ze mnie coraz więcej"]',2,'dungeon',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_bones','Żywych niosę, umarłym nie służę. Czym jestem?','statek','["łódź","okręt","tratwa"]','["Pływam po wodzie","Przewożę ludzi","Rozsypuję się gdy umrę"]',2,'death',1,'2026-05-24 17:04:56');
INSERT INTO game_config_riddles VALUES('riddle_sword','Tnę bez ostrzy, jestem ostry lecz nie ze stali. Czym jestem?','wiatr','["wicher","podmuch","burza"]','["Nie mam ciała","Możesz mnie poczuć ale nie dotknąć","Poruszam drzewami"]',2,'nature',1,'2026-05-24 17:04:56');
INSERT INTO adventure_ideas VALUES(1,'Zamek Drachenfels','Drużyna przypadkowych śmiałków trafia pod mury przeklętego zamku Drachenfels, zwabiona plotkami o skarbie, sekretach i nieumarłych strażnikach. Wnętrze ruin okazuje się żywym labiryntem, który testuje ich spryt, odwagę i zdrowy rozsądek, a każda odpowiedź rodzi kolejne zagrożenie.','["dark", "gothic", "mystery", "horror"]','["ancient evil", "isolation", "illusion", "corruption", "survival"]','hard','{"title": "Zamek Drachenfels", "premise": "Drużyna przypadkowych śmiałków trafia pod mury przeklętego zamku Drachenfels, zwabiona plotkami o skarbie, sekretach i nieumarłych strażnikach. Wnętrze ruin okazuje się żywym labiryntem, który testuje ich spryt, odwagę i zdrowy rozsądek, a każda odpowiedź rodzi kolejne zagrożenie.", "tone": ["dark", "gothic", "mystery", "horror"], "themes": ["ancient evil", "isolation", "illusion", "corruption", "survival"], "difficulty": "hard", "arcs": [{"title": "Wejście do legendy", "description": "Bohaterowie docierają pod zamek i od razu czują, że miejsce jest skażone czymś, co nie powinno istnieć. Ruiny, cisza i plotki o dawnym czarnoksiężniku budują napięcie jeszcze przed wejściem.", "scene_goals": ["Przedstawić skalę i izolację zamku", "Wzmocnić poczucie, że to miejsce ma własną wolę", "Zachęcić drużynę do wejścia mimo złych przeczuć"], "private_twist": "Zamek od początku reaguje na obecność drużyny, jakby rozpoznawał w nich role potrzebne do odtworzenia dawnego rytuału."}, {"title": "Pierwsze niepokoje", "description": "W pierwszych korytarzach pojawiają się ślady dawnych mieszkańców, echa rytuałów i oznaki, że zamek nie jest martwy. Proste przejścia stają się próbą orientacji, bo przestrzeń zaczyna oszukiwać.", "scene_goals": ["Pokazać, że zamek jest nielogiczny", "Wprowadzić pierwsze drobne zagrożenia", "Zasiać niepewność co do własnych zmysłów"], "private_twist": "Niektóre korytarze są iluzoryczne i prowadzą do tych samych miejsc pod innym kątem, tworząc ukryty mechanizm labiryntu."}, {"title": "Żyjący zamek", "description": "Iluzje, pułapki i zniekształcenia rzeczywistości nasilają się, a sam zamek zdaje się badać lęki bohaterów. Drużyna musi rozróżniać prawdę od podszeptów i fałszywych tropów.", "scene_goals": ["Zwiększyć paranoję", "Zmuszać graczy do podejmowania ryzyka", "Pokazać, że zamek aktywnie poluje na ich słabości"], "private_twist": "Zamek nie tylko broni się przed intruzami — on selekcjonuje ich, próbując wyłonić tych, których da się złamać i skazić."}, {"title": "Ślady dawnej historii", "description": "Drużyna odkrywa fragmenty historii Drachenfelsa poprzez zapiski, symbole, zjawy i reakcje ruin na jego imię. Prawda o zamku wychodzi na jaw stopniowo, w sposób niepełny i niepokojący.", "scene_goals": ["Ujawnić część mitologii Drachenfelsa", "Wiązać sekrety zamku z bieżącym zagrożeniem", "Nagradzać uważną eksplorację"], "private_twist": "Drachenfels nie został po prostu pokonany — część jego woli została wtopiona w samą strukturę zamku."}, {"title": "Coraz głębiej", "description": "Im dalej w głąb, tym bardziej zamek przypomina żywy grobowiec pełen strażników, echa dawnych wydarzeń i istot związanych z mroczną mocą. Walki są rzadsze, ale cięższe, a każdy zwyciężony przeciwnik odsłania większy koszt wyprawy.", "scene_goals": ["Podnieść stawkę każdego starcia", "Wprowadzić przeciwników związanych z klątwą", "Utrzymać tempo eksploracji i zagrożenia"], "private_twist": "Niektórzy przeciwnicy są odbiciami dawnych ofiar zamku, a nie samodzielnymi potworami."}, {"title": "Konfrontacja z centrum", "description": "Drużyna dociera do serca zamku i staje twarzą w twarz ze źródłem skażenia. Okazuje się, że pokonanie jednego wroga nie wystarczy, bo zagrożenie ma charakter rytuału, klątwy i obecności zarazem.", "scene_goals": ["Zbudować kulminację grozy", "Wystawić drużynę na największe zagrożenie", "Dać wybór: zniszczyć, odciąć, uwięzić albo uciec"], "private_twist": "Źródło zła może wymagać ofiary, by zostać osłabione — i zamek spróbuje wymusić tę cenę na bohaterach."}, {"title": "Finał i ucieczka", "description": "Zakończenie to walka o przetrwanie i domknięcie klątwy, nie triumfalne zwycięstwo. Bohaterowie uciekają z zamku, który rozpada się, zamyka lub pożera własne wnętrze, zostawiając po sobie niedopowiedzenie.", "scene_goals": ["Domknąć główny konflikt", "Zostawić poczucie częściowego zwycięstwa", "Zbudować mocny, gorzki finał"], "private_twist": "Nawet jeśli zamek zostanie opuszczony, coś z niego wychodzi razem z drużyną."}], "hooks": [{"type": "location", "title": "Zamek Drachenfels", "description": "Przeklęta twierdza w ruinie, pełna iluzji, martwych strażników i pokoi, które nie powinny istnieć. Sama architektura jest częścią zagadki i zagrożenia.", "significance": "central", "draft_data": {"role": "główna lokacja przygody", "features": ["labirynt", "iluzje", "strażnicy", "rytualne komnaty", "fałszywe przejścia"]}}, {"type": "enemy", "title": "Martwi strażnicy", "description": "Nieumarli lub pół-umarli obrońcy ruin, którzy nie tyle patrolują, co wykonują dawno utrwalony rozkaz. Ich obecność sugeruje, że zamek nadal ma system obronny.", "significance": "major", "draft_data": {"behavior": "obrona kluczowych przejść", "role": "pierwsza poważna przeszkoda bojowa"}}, {"type": "theme", "title": "Iluzja i niepewność", "description": "Zamek stale podważa percepcję drużyny, tworząc fałszywe ściany, echa i pozorne bezpieczeństwo. Gracze nigdy nie powinni być pewni, czy widzą rzeczywistość.", "significance": "central", "draft_data": {"use": "paranoja, zwodzenie, labirynt"}}, {"type": "npc", "title": "Echo dawnego sługi", "description": "Zjawa lub ślad pamięci, który może przekazać fragment historii zamku, ale nigdy całość. Pomaga tylko tyle, by zbudować jeszcze większy niepokój.", "significance": "major", "draft_data": {"function": "ekspozycja i atmosfera", "reliability": "niepełna"}}, {"type": "item", "title": "Zapiski o Drachenfelsie", "description": "Porozrzucane notatki, herby, szkice i rytualne formuły pozwalające zrozumieć, co naprawdę dzieje się w zamku. Mogą też zdradzić, jak osłabić jego wpływ.", "significance": "major", "draft_data": {"use": "lore, wskazówki, rozwiązanie finału"}}, {"type": "event", "title": "Zamknięcie przejść", "description": "W pewnym momencie zamek odcina drogę odwrotu, zmuszając drużynę do dalszej eksploracji lub desperackiego szukania alternatywnego wyjścia.", "significance": "major", "draft_data": {"function": "eskalacja i presja czasowa"}}], "player_hook": "Bohaterowie wchodzą do zamku jako przypadkowi odkrywcy, kuszeni plotką o skarbie, sekretach i sławie. Szybko okazuje się jednak, że jeśli chcą wyjść żywi, muszą najpierw zrozumieć reguły miejsca, które samo ich wybrało.", "gm_private": "Drachenfels nie jest tylko wspomnieniem ani duchem — jego obecność została częściowo wpisana w strukturę zamku, więc każda próba walki z nim może tylko chwilowo osłabić wpływ klątwy. Największy sekret: zamek testuje drużynę pod kątem tego, kto nadaje się na kolejny nośnik jego mocy."}','draft','admin','2026-05-27 16:22:53');
INSERT INTO adventure_ideas VALUES(3,'Cienie Zagubionych Królestw','Starożytne królestwo Valdoria zniknęło z map tysiąc lat temu. Teraz jego ruiny budzą się do życia, a z podziemi wyłaniają się istoty z legend. Gracze odkrywają, że klątwa, która pochłonęła Valdorię, może rozprzestrzenić się na cały świat — chyba że znajdą siedem Pieczęci Zapomnianego Króla i złamią rytuał.','["mroczny", "tajemniczy", "epicki"]','["starożytna klątwa", "zapomniana historia", "ofiara"]','medium','{"title": "Cienie Zagubionych Królestw", "premise": "Starożytne królestwo Valdoria zniknęło z map tysiąc lat temu. Teraz jego ruiny budzą się do życia, a z podziemi wyłaniają się istoty z legend. Gracze odkrywają, że klątwa, która pochłonęła Valdorię, może rozprzestrzenić się na cały świat — chyba że znajdą siedem Pieczęci Zapomnianego Króla i złamią rytuał.", "tone": ["mroczny", "tajemniczy", "epicki"], "themes": ["starożytna klątwa", "zapomniana historia", "ofiara"], "difficulty": "medium", "arcs": [], "hooks": []}','draft','admin','2026-05-28 06:25:20');
INSERT INTO adventure_ideas VALUES(4,'Klątwa Żelaznego Lasu','Heroes investigate strange disappearances in an ancient iron forest cursed by a forgotten druid.','["dark", "mysterious", "hopeful"]','["nature vs civilization", "ancient curse", "redemption"]','hard','{"title": "Klątwa Żelaznego Lasu", "premise": "Heroes investigate strange disappearances in an ancient iron forest cursed by a forgotten druid.", "tone": ["dark", "mysterious", "hopeful"], "themes": ["nature vs civilization", "ancient curse", "redemption"], "difficulty": "hard", "arcs": [], "hooks": []}','draft','admin','2026-05-28 07:20:26');
INSERT INTO adventure_ideas VALUES(5,'Oblężenie Ostatniej Wioski','Bohater przypadkiem trafia do miasteczka Dębowa Przystań, które od tygodni jest nękane przez coraz śmielsze bandy goblinów z pobliskiego lasu. Mieszkańcy są przerażeni i zdemoralizowani - potrzebują przywódcy. Gracz musi zorganizować obronę, podnieść morale osadników, wzmocnić umocnienia, a następnie poprowadzić lokalną milicję w decydującym ataku na obóz goblinów.','["epickie", "komediowy", "dynamiczny"]','["przetrwanie", "przywództwo", "walka"]','easy','{"title": "Oblężenie Ostatniej Wioski", "premise": "Bohater przypadkiem trafia do miasteczka Dębowa Przystań, które od tygodni jest nękane przez coraz śmielsze bandy goblinów z pobliskiego lasu. Mieszkańcy są przerażeni i zdemoralizowani - potrzebują przywódcy. Gracz musi zorganizować obronę, podnieść morale osadników, wzmocnić umocnienia, a następnie poprowadzić lokalną milicję w decydującym ataku na obóz goblinów.", "tone": ["epickie", "komediowy", "dynamiczny"], "themes": ["przetrwanie", "przywództwo", "walka"], "difficulty": "easy", "arcs": [], "hooks": []}','draft','admin','2026-05-28 07:41:11');
INSERT INTO adventure_ideas VALUES(6,'Zaginione Miasto Cieni','Doświadczony poszukiwacz przygód odnajduje drogę do legendarnego, opuszczonego miasta Umbravale, ukrytego pośrodku pradawnego lasu. Mieszkańcy zniknęli bez śladu, a w ruinach pozostały skarby i zakazana wiedza. W cieniu porośniętych mchem ulic działa jednak tajemniczy kult Cichych Strażników, który za wszelką cenę chroni prawdę o upadku miasta.','["przygodowy", "tajemniczy", "noir"]','["odkrycie", "zakazana wiedza", "kult i tajemnica"]','medium','{"title": "Zaginione Miasto Cieni", "premise": "Doświadczony poszukiwacz przygód odnajduje drogę do legendarnego, opuszczonego miasta Umbravale, ukrytego pośrodku pradawnego lasu. Mieszkańcy zniknęli bez śladu, a w ruinach pozostały skarby i zakazana wiedza. W cieniu porośniętych mchem ulic działa jednak tajemniczy kult Cichych Strażników, który za wszelką cenę chroni prawdę o upadku miasta.", "tone": ["przygodowy", "tajemniczy", "noir"], "themes": ["odkrycie", "zakazana wiedza", "kult i tajemnica"], "difficulty": "medium", "arcs": [], "hooks": []}','draft','admin','2026-05-28 10:03:16');
INSERT INTO adventure_ideas VALUES(7,'Krew pod Kamiennym Wzgórzem','Podróżny zatrzymuje się na noc w miasteczku Kamienne Wzgórze, którego mieszkańcy od miesięcy żyją w strachu przed nocnymi najściami rzekomych wampirów. Gdy narasta panika, a ziemia pod domami zaczyna drżeć, wychodzi na jaw, że wampiry nie są najeźdźcami, lecz tragicznymi strażnikami pieczęci więżącej starożytne zło pod miastem. Najokrutniejsza prawda jest jednak taka, że sami mieszkańcy od pokoleń, poprzez źle rozumiane rytuały ochronne, karmią byt, którego tak bardzo się boją.','["dark", "brutal", "siege", "mystery", "gothic", "tragic"]','["misjudgment", "sacrifice", "ancient evil", "fear", "moral ambiguity", "mob violence", "false piety"]','medium','{"title": "Krew pod Kamiennym Wzgórzem", "premise": "Podróżny zatrzymuje się na noc w miasteczku Kamienne Wzgórze, którego mieszkańcy od miesięcy żyją w strachu przed nocnymi najściami rzekomych wampirów. Gdy narasta panika, a ziemia pod domami zaczyna drżeć, wychodzi na jaw, że wampiry nie są najeźdźcami, lecz tragicznymi strażnikami pieczęci więżącej starożytne zło pod miastem. Najokrutniejsza prawda jest jednak taka, że sami mieszkańcy od pokoleń, poprzez źle rozumiane rytuały ochronne, karmią byt, którego tak bardzo się boją.", "tone": ["dark", "brutal", "siege", "mystery", "gothic", "tragic"], "themes": ["misjudgment", "sacrifice", "ancient evil", "fear", "moral ambiguity", "mob violence", "false piety"], "difficulty": "medium", "arcs": [{"title": "Zmrok nad Kamiennym Wzgórzem", "description": "Gracz przybywa do miasteczka tuż przed zamknięciem bram. Ludzie w pośpiechu barykadują domy, wynoszą święte symbole, ostrzą widły i szykują się na kolejną noc oblężenia. Obcy zostaje natychmiast wciągnięty w lokalny konflikt i poproszony o pomoc w odparciu ''krwiopijców''.", "scene_goals": ["Wprowadzić atmosferę zaszczucia i zbiorowej paranoi", "Poznać najważniejszych mieszkańców i ich wersję wydarzeń", "Zasugerować, że ataki wampirów nie pasują do typowego polowania"], "private_twist": "Wiele domów oznaczonych jako ''zaatakowane'' nosi ślady walki od wewnątrz, jakby zagrożenie pojawiało się najpierw pośród samych mieszkańców."}, {"title": "Noc czerwonych dachów", "description": "Po zmroku rozlega się alarm. Coś porusza się po dachach, a z piwnic i szczelin w ziemi wydostają się wynaturzone istoty lub opętani mieszkańcy. W chaosie walki gracz może zobaczyć, że wampiry nie atakują bezmyślnie, lecz osłaniają wybrane domy, wynoszą rannych i zabijają tylko tych, którzy zdają się już skażeni.", "scene_goals": ["Zaoferować dynamiczną, brutalną scenę walki", "Pokazać niejednoznaczną rolę wampirów", "Stworzyć okazję do uratowania ważnego NPC lub zdobycia pierwszego dowodu"], "private_twist": "Jedna z ofiar uznanych za ''zabitych przez wampira'' była w istocie na skraju przemiany pod wpływem mocy spod miasta."}, {"title": "Pod kaplicą, pod studnią, pod kłamstwem", "description": "Po nocy gracz może prowadzić śledztwo: badać ciała, rozmawiać z ocalałymi, przeszukać kaplicę, kryptę, archiwa burmistrza i starą studnię. Tropy prowadzą do prawdy o dawnym pakcie, ofiarach składanych ziemi i straży pełnionej przez wampiry od pokoleń.", "scene_goals": ["Połączyć wskazówki w spójną prawdę o miasteczku", "Odkryć, że mieszkańcy sami podtrzymują zagrożenie", "Doprowadzić do spotkania z przywódczynią wampirów"], "private_twist": "Najstarsze rody nie tylko wiedziały o rytuałach, ale celowo utrzymywały lud w niewiedzy, by zachować władzę i tłumaczyć własne przywileje ''ochroną miasteczka''."}, {"title": "Oblężenie pieczęci", "description": "Tłum mieszkańców, podburzony strachem i religijną furią, rusza spalić kryjówkę wampirów albo zbezcześcić miejsce pieczęci. W tym samym czasie zło pod miastem wybija się na powierzchnię poprzez pęknięcia ziemi, szał, krew i mutacje. Gracz musi wybrać: stanąć z tłumem, przekonać go do odwrotu albo sprzymierzyć się z wampirami i wspólnie utrzymać pieczęć za straszliwą cenę.", "scene_goals": ["Zamknąć historię wielostronnym konfliktem", "Wymusić moralny wybór bez czystego rozwiązania", "Pozwolić graczowi zdecydować o losie miasteczka i strażników"], "private_twist": "Nawet w najlepszym zakończeniu pieczęć nie zostaje całkowicie naprawiona — Kamienne Wzgórze pozostaje miejscem przeklętym, wymagającym dalszej straży, ofiar albo opuszczenia."}], "hooks": [{"type": "location", "title": "Kamienne Wzgórze", "description": "Małe, ponure miasteczko zbudowane na starszych niż pamięć fundamentach. Nad dachami góruje popękana kaplica, a pośrodku placu stoi stara studnia, wokół której mieszkańcy zostawiają drobne dary ''na szczęście''.", "significance": "central", "draft_data": {"notable_features": ["plac ze studnią", "kaplica św. Varda z podziemną kryptą", "dom burmistrza z zamkniętym archiwum", "opuszczony młyn przy mokradłach", "cmentarz z zapadniętymi grobami", "spalona stodoła po ostatnim ''ataku''"], "mood": "strach, zabobon, gniew i zmęczenie"}}, {"type": "npc", "title": "Burmistrz Edrik Voss", "description": "Przywódca miasteczka, wyczerpany i coraz bardziej desperacki. Publicznie nawołuje do wybicia wampirów, prywatnie zaś panicznie boi się prawdy o tym, co jego przodkowie ukryli pod miastem.", "significance": "major", "draft_data": {"role": "lokalny przywódca", "public_face": "obrońca ludzi", "secret": "posiada księgę rodową opisującą dawne rytuały i część paktu", "motivation": "ocalić miasteczko bez ujawniania winy własnego rodu"}}, {"type": "npc", "title": "Matka Ilse", "description": "Starsza opiekunka kaplicy, surowa i pobożna. Uważa wampiry za narzędzie kary, ale zna stare modlitwy, które są w rzeczywistości zniekształconymi formułami pieczęci.", "significance": "major", "draft_data": {"role": "autorytet religijny", "secret": "nie rozumie pełnego sensu obrzędów, które odprawia od lat", "use_in_game": "może dać trop do krypty lub nieświadomie przyspieszyć katastrofę"}}, {"type": "npc", "title": "Lady Mirena", "description": "Przywódczyni kręgu wampirów, dawna szlachcianka związana z miejscem od stuleci. Wyniszczona długą strażą, chłodna w obyciu, ale autentycznie oddana ochronie ludzi, którzy jej nienawidzą.", "significance": "central", "draft_data": {"role": "wampirza strażniczka", "motivation": "utrzymać pieczęć i ocalić tyle istnień, ile się da", "method": "żywi się rzadko, w kontrolowany sposób, czasem na ochotnikach z dawnych rodów", "impression": "groźna, smutna, dumna"}}, {"type": "npc", "title": "Toma, syn młynarza", "description": "Młody chłopak, który twierdzi, że widział wampira ratującego jego siostrę przed czymś wychodzącym z piwnicy. Nikt mu nie wierzy, bo po ataku zaczął mieć krwawe sny i napady drgawek.", "significance": "minor", "draft_data": {"role": "świadek", "use_in_game": "może potwierdzić niejednoznaczność wampirów i wskazać miejsce skażenia"}}, {"type": "npc", "title": "Hagen Rupp", "description": "Miejscowy rzeźnik i herszt najbardziej agresywnej części tłumu. Stracił żonę podczas jednego z nocnych incydentów i pragnie zemsty, nieważne na kim.", "significance": "major", "draft_data": {"role": "przywódca tłumu", "motivation": "zemsta i odzyskanie poczucia kontroli", "secret": "jego żona była już częściowo skażona wpływem bytu spod miasta"}}, {"type": "enemy", "title": "To, Co Tętni Pod Miastem", "description": "Starożytna obecność uwięziona pod Kamiennym Wzgórzem, być może pozostałość po przedludzkim kulcie, może larwalny demon, a może bezimienny byt z głębi ziemi. Nie ma jednej formy — objawia się przez pulsującą ziemię, krew, szał, mutacje i sny.", "significance": "central", "draft_data": {"manifestations": ["krwawe sny", "nagłe akty przemocy", "deformacje ciał", "głos dobiegający ze studni", "pulsowanie kamieni pod kaplicą"], "goal": "zebrać dość ofiar i emocji, by wyrwać się spod pieczęci"}}, {"type": "location", "title": "Krypta Pieczęci", "description": "Ukryta komora pod kaplicą i studnią, gdzie stare kamienie są popękane od wewnętrznego nacisku. Na ścianach widnieją ślady dawnych rytuałów ochronnych i krwawych ofiar.", "significance": "central", "draft_data": {"features": ["kamienny krąg pieczęci", "rynny na krew", "szczelina wydzielająca ciepło i odór żelaza", "stare herby rodów założycielskich"]}}, {"type": "event", "title": "Noc Pękającej Ziemi", "description": "Kulminacyjna noc, w której pieczęć zaczyna się rozpadać, a napięcie społeczne wybucha otwartą przemocą. Dokładnie wtedy, gdy mieszkańcy polują na swoich rzekomych oprawców, prawdziwe zagrożenie przebija się do świata.", "significance": "major", "draft_data": {"stakes": "jeśli pieczęć pęknie, miasteczko stanie się pierwszym żerowiskiem budzącego się bytu"}}, {"type": "theme", "title": "Strażnicy przeklęci przez wdzięczność, której nigdy nie dostaną", "description": "Wampiry pełnią rolę obrońców, ale ich natura sprawia, że nikt nie uzna ich poświęcenia. Każda ich interwencja pogłębia tylko nienawiść i strach.", "significance": "central", "draft_data": {}}], "player_hook": "Podróżny zostaje zmuszony do nocnego postoju w Kamiennym Wzgórzu, gdy bramy zostają zamknięte przed zmrokiem, a mieszkańcy błagają każdego zdolnego do walki o pomoc. Jako obcy, nie należy do lokalnych układów ani dawnych rodów, więc może dostrzec sprzeczności, których mieszkańcy nie chcą lub nie potrafią zobaczyć.", "gm_private": "Wampiry są spadkobiercami dawnego paktu zawartego po katastrofie sprzed pokoleń, kiedy założyciele miasta obudzili byt pod wzgórzem podczas wydobycia lub bluźnierczego rytuału. Aby utrzymać pieczęć, potrzebna była krew, czujność i gotowość do eliminowania tych, których byt już skaził. Z czasem prawda została wyparta i przerobiona na ludowe rytuały ochronne: krople krwi wrzucane do studni, dary zostawiane na placu, obrzędy w kaplicy. Wszystko to miało pierwotnie wzmacniać kontrolę nad pieczęcią, ale z biegiem lat zostało zniekształcone i zaczęło bardziej karmić uwięzioną obecność niż ją wiązać.", "investigation_clues": [{"clue": "Na ciałach rzekomych ofiar wampirów część ran wygląda jak zadane pośmiertnie lub w akcie litości, nie podczas żerowania.", "leads_to": "Podważa prostą narrację o drapieżnikach polujących dla głodu."}, {"clue": "W jednym z domów ślady krwi prowadzą z piwnicy na zewnątrz, a nie od okna do środka.", "leads_to": "Sugeruje, że zagrożenie wychodzi spod ziemi lub z wnętrza domu."}, {"clue": "Dary przy studni zawierają krew zwierząt, mleko i drobne kości, składane według bardzo starego wzoru.", "leads_to": "Pozwala połączyć zwyczaj mieszkańców z dawnym rytuałem pieczęci."}, {"clue": "W księdze rodowej Vossów znajduje się wzmianka o ''nocnych strażnikach'', których lud miał nienawidzić, ale którym nie wolno było przeszkadzać.", "leads_to": "Potwierdza istnienie dawnego układu z wampirami."}, {"clue": "Matka Ilse odmawia modlitwę, której słowa bardziej przypominają zaklęcie wiążące niż nabożeństwo.", "leads_to": "Naprowadza na kaplicę i kryptę pieczęci."}, {"clue": "Toma opisuje, że wampir wyniósł jego siostrę z domu, zanim podłoga zapadła się do rozgrzanej szczeliny.", "leads_to": "Pokazuje, że przynajmniej jeden ''atak'' był aktem ratunku."}], "set_piece_scenes": [{"title": "Obrona spalonej stodoły", "description": "Gracz wraz z mieszkańcami broni grupy ocalałych zamkniętych w stodole, podczas gdy po dachu przemykają sylwetki wampirów, a spod podłogi próbują wedrzeć się skażeni ludzie lub wynaturzone istoty."}, {"title": "Pościg przez dachy i dzwonnicę", "description": "Po nocnym alarmie gracz może ścigać wampira, który porwał dziecko — tylko po to, by odkryć, że wynosił je z domu, w którym coś budziło się w piwnicy."}, {"title": "Starcie przy studni", "description": "Rozjuszony tłum chce wrzucić do studni symbole ochronne i podpalić plac, nie wiedząc, że narusza ostatnie warstwy pieczęci."}, {"title": "Finał w Krypcie Pieczęci", "description": "Kamienie pękają, krew spływa rytualnymi rynnami, a wampiry i ludzie walczą ramię w ramię albo przeciw sobie, gdy byt spod miasta próbuje przebić się przez szczelinę."}], "possible_endings": [{"title": "Sojusz potępionych", "description": "Gracz przekonuje część mieszkańców lub ignoruje ich gniew i staje z wampirami do obrony pieczęci. Zło zostaje chwilowo zatrzymane, ale miasteczko musi żyć dalej pod strażą istot, których nadal się boi."}, {"title": "Zwycięstwo tłumu, triumf ciemności", "description": "Wampiry zostają wybite lub przepędzone, a mieszkańcy świętują krótko, zanim pieczęć pęka i prawdziwe zło zaczyna pożerać miasto od środka."}, {"title": "Krwawe odkupienie", "description": "Prawda wychodzi na jaw, ale utrzymanie pieczęci wymaga ofiary z jednego z rodów założycielskich, z samego burmistrza albo z kogoś dobrowolnie podejmującego rolę nowego strażnika."}, {"title": "Ucieczka z przeklętego miejsca", "description": "Gracz przeżywa noc grozy i opuszcza miasteczko, zostawiając jego los nierozstrzygnięty. Za plecami słyszy dzwony, krzyki i trzepot skrzydeł nad dachami."}]}','draft','admin','2026-05-29 10:29:09');
INSERT INTO adventure_ideas VALUES(8,'Krew pod Kamiennym Wzgórzem','Podróżny zatrzymuje się na noc w miasteczku Kamienne Wzgórze, którego mieszkańcy od miesięcy żyją w strachu przed nocnymi najściami rzekomych wampirów. Gdy narasta panika, a ziemia pod domami zaczyna drżeć, wychodzi na jaw, że wampiry nie są najeźdźcami, lecz tragicznymi strażnikami pieczęci więżącej starożytne zło pod miastem. Najokrutniejsza prawda jest jednak taka, że sami mieszkańcy od pokoleń, poprzez źle rozumiane rytuały ochronne, karmią byt, którego tak bardzo się boją.','["dark", "brutal", "siege", "mystery", "gothic", "tragic"]','["misjudgment", "sacrifice", "ancient evil", "fear", "moral ambiguity", "mob violence", "false piety"]','medium','{"title": "Krew pod Kamiennym Wzgórzem", "premise": "Podróżny zatrzymuje się na noc w miasteczku Kamienne Wzgórze, którego mieszkańcy od miesięcy żyją w strachu przed nocnymi najściami rzekomych wampirów. Gdy narasta panika, a ziemia pod domami zaczyna drżeć, wychodzi na jaw, że wampiry nie są najeźdźcami, lecz tragicznymi strażnikami pieczęci więżącej starożytne zło pod miastem. Najokrutniejsza prawda jest jednak taka, że sami mieszkańcy od pokoleń, poprzez źle rozumiane rytuały ochronne, karmią byt, którego tak bardzo się boją.", "tone": ["dark", "brutal", "siege", "mystery", "gothic", "tragic"], "themes": ["misjudgment", "sacrifice", "ancient evil", "fear", "moral ambiguity", "mob violence", "false piety"], "difficulty": "medium", "arcs": [{"title": "Zmrok nad Kamiennym Wzgórzem", "description": "Gracz przybywa do miasteczka tuż przed zamknięciem bram. Ludzie w pośpiechu barykadują domy, wynoszą święte symbole, ostrzą widły i szykują się na kolejną noc oblężenia. Obcy zostaje natychmiast wciągnięty w lokalny konflikt i poproszony o pomoc w odparciu ''krwiopijców''.", "scene_goals": ["Wprowadzić atmosferę zaszczucia i zbiorowej paranoi", "Poznać najważniejszych mieszkańców i ich wersję wydarzeń", "Zasugerować, że ataki wampirów nie pasują do typowego polowania"], "private_twist": "Wiele domów oznaczonych jako ''zaatakowane'' nosi ślady walki od wewnątrz, jakby zagrożenie pojawiało się najpierw pośród samych mieszkańców."}, {"title": "Noc czerwonych dachów", "description": "Po zmroku rozlega się alarm. Coś porusza się po dachach, a z piwnic i szczelin w ziemi wydostają się wynaturzone istoty lub opętani mieszkańcy. W chaosie walki gracz może zobaczyć, że wampiry nie atakują bezmyślnie, lecz osłaniają wybrane domy, wynoszą rannych i zabijają tylko tych, którzy zdają się już skażeni.", "scene_goals": ["Zaoferować dynamiczną, brutalną scenę walki", "Pokazać niejednoznaczną rolę wampirów", "Stworzyć okazję do uratowania ważnego NPC lub zdobycia pierwszego dowodu"], "private_twist": "Jedna z ofiar uznanych za ''zabitych przez wampira'' była w istocie na skraju przemiany pod wpływem mocy spod miasta."}, {"title": "Pod kaplicą, pod studnią, pod kłamstwem", "description": "Po nocy gracz może prowadzić śledztwo: badać ciała, rozmawiać z ocalałymi, przeszukać kaplicę, kryptę, archiwa burmistrza i starą studnię. Tropy prowadzą do prawdy o dawnym pakcie, ofiarach składanych ziemi i straży pełnionej przez wampiry od pokoleń.", "scene_goals": ["Połączyć wskazówki w spójną prawdę o miasteczku", "Odkryć, że mieszkańcy sami podtrzymują zagrożenie", "Doprowadzić do spotkania z przywódczynią wampirów"], "private_twist": "Najstarsze rody nie tylko wiedziały o rytuałach, ale celowo utrzymywały lud w niewiedzy, by zachować władzę i tłumaczyć własne przywileje ''ochroną miasteczka''."}, {"title": "Oblężenie pieczęci", "description": "Tłum mieszkańców, podburzony strachem i religijną furią, rusza spalić kryjówkę wampirów albo zbezcześcić miejsce pieczęci. W tym samym czasie zło pod miastem wybija się na powierzchnię poprzez pęknięcia ziemi, szał, krew i mutacje. Gracz musi wybrać: stanąć z tłumem, przekonać go do odwrotu albo sprzymierzyć się z wampirami i wspólnie utrzymać pieczęć za straszliwą cenę.", "scene_goals": ["Zamknąć historię wielostronnym konfliktem", "Wymusić moralny wybór bez czystego rozwiązania", "Pozwolić graczowi zdecydować o losie miasteczka i strażników"], "private_twist": "Nawet w najlepszym zakończeniu pieczęć nie zostaje całkowicie naprawiona — Kamienne Wzgórze pozostaje miejscem przeklętym, wymagającym dalszej straży, ofiar albo opuszczenia."}], "hooks": [{"type": "location", "title": "Kamienne Wzgórze", "description": "Małe, ponure miasteczko zbudowane na starszych niż pamięć fundamentach. Nad dachami góruje popękana kaplica, a pośrodku placu stoi stara studnia, wokół której mieszkańcy zostawiają drobne dary ''na szczęście''.", "significance": "central", "draft_data": {"notable_features": ["plac ze studnią", "kaplica św. Varda z podziemną kryptą", "dom burmistrza z zamkniętym archiwum", "opuszczony młyn przy mokradłach", "cmentarz z zapadniętymi grobami", "spalona stodoła po ostatnim ''ataku''"], "mood": "strach, zabobon, gniew i zmęczenie"}}, {"type": "npc", "title": "Burmistrz Edrik Voss", "description": "Przywódca miasteczka, wyczerpany i coraz bardziej desperacki. Publicznie nawołuje do wybicia wampirów, prywatnie zaś panicznie boi się prawdy o tym, co jego przodkowie ukryli pod miastem.", "significance": "major", "draft_data": {"role": "lokalny przywódca", "public_face": "obrońca ludzi", "secret": "posiada księgę rodową opisującą dawne rytuały i część paktu", "motivation": "ocalić miasteczko bez ujawniania winy własnego rodu"}}, {"type": "npc", "title": "Matka Ilse", "description": "Starsza opiekunka kaplicy, surowa i pobożna. Uważa wampiry za narzędzie kary, ale zna stare modlitwy, które są w rzeczywistości zniekształconymi formułami pieczęci.", "significance": "major", "draft_data": {"role": "autorytet religijny", "secret": "nie rozumie pełnego sensu obrzędów, które odprawia od lat", "use_in_game": "może dać trop do krypty lub nieświadomie przyspieszyć katastrofę"}}, {"type": "npc", "title": "Lady Mirena", "description": "Przywódczyni kręgu wampirów, dawna szlachcianka związana z miejscem od stuleci. Wyniszczona długą strażą, chłodna w obyciu, ale autentycznie oddana ochronie ludzi, którzy jej nienawidzą.", "significance": "central", "draft_data": {"role": "wampirza strażniczka", "motivation": "utrzymać pieczęć i ocalić tyle istnień, ile się da", "method": "żywi się rzadko, w kontrolowany sposób, czasem na ochotnikach z dawnych rodów", "impression": "groźna, smutna, dumna"}}, {"type": "npc", "title": "Toma, syn młynarza", "description": "Młody chłopak, który twierdzi, że widział wampira ratującego jego siostrę przed czymś wychodzącym z piwnicy. Nikt mu nie wierzy, bo po ataku zaczął mieć krwawe sny i napady drgawek.", "significance": "minor", "draft_data": {"role": "świadek", "use_in_game": "może potwierdzić niejednoznaczność wampirów i wskazać miejsce skażenia"}}, {"type": "npc", "title": "Hagen Rupp", "description": "Miejscowy rzeźnik i herszt najbardziej agresywnej części tłumu. Stracił żonę podczas jednego z nocnych incydentów i pragnie zemsty, nieważne na kim.", "significance": "major", "draft_data": {"role": "przywódca tłumu", "motivation": "zemsta i odzyskanie poczucia kontroli", "secret": "jego żona była już częściowo skażona wpływem bytu spod miasta"}}, {"type": "enemy", "title": "To, Co Tętni Pod Miastem", "description": "Starożytna obecność uwięziona pod Kamiennym Wzgórzem, być może pozostałość po przedludzkim kulcie, może larwalny demon, a może bezimienny byt z głębi ziemi. Nie ma jednej formy — objawia się przez pulsującą ziemię, krew, szał, mutacje i sny.", "significance": "central", "draft_data": {"manifestations": ["krwawe sny", "nagłe akty przemocy", "deformacje ciał", "głos dobiegający ze studni", "pulsowanie kamieni pod kaplicą"], "goal": "zebrać dość ofiar i emocji, by wyrwać się spod pieczęci"}}, {"type": "location", "title": "Krypta Pieczęci", "description": "Ukryta komora pod kaplicą i studnią, gdzie stare kamienie są popękane od wewnętrznego nacisku. Na ścianach widnieją ślady dawnych rytuałów ochronnych i krwawych ofiar.", "significance": "central", "draft_data": {"features": ["kamienny krąg pieczęci", "rynny na krew", "szczelina wydzielająca ciepło i odór żelaza", "stare herby rodów założycielskich"]}}, {"type": "event", "title": "Noc Pękającej Ziemi", "description": "Kulminacyjna noc, w której pieczęć zaczyna się rozpadać, a napięcie społeczne wybucha otwartą przemocą. Dokładnie wtedy, gdy mieszkańcy polują na swoich rzekomych oprawców, prawdziwe zagrożenie przebija się do świata.", "significance": "major", "draft_data": {"stakes": "jeśli pieczęć pęknie, miasteczko stanie się pierwszym żerowiskiem budzącego się bytu"}}, {"type": "theme", "title": "Strażnicy przeklęci przez wdzięczność, której nigdy nie dostaną", "description": "Wampiry pełnią rolę obrońców, ale ich natura sprawia, że nikt nie uzna ich poświęcenia. Każda ich interwencja pogłębia tylko nienawiść i strach.", "significance": "central", "draft_data": {}}], "player_hook": "Podróżny zostaje zmuszony do nocnego postoju w Kamiennym Wzgórzu, gdy bramy zostają zamknięte przed zmrokiem, a mieszkańcy błagają każdego zdolnego do walki o pomoc. Jako obcy, nie należy do lokalnych układów ani dawnych rodów, więc może dostrzec sprzeczności, których mieszkańcy nie chcą lub nie potrafią zobaczyć.", "gm_private": "Wampiry są spadkobiercami dawnego paktu zawartego po katastrofie sprzed pokoleń, kiedy założyciele miasta obudzili byt pod wzgórzem podczas wydobycia lub bluźnierczego rytuału. Aby utrzymać pieczęć, potrzebna była krew, czujność i gotowość do eliminowania tych, których byt już skaził. Z czasem prawda została wyparta i przerobiona na ludowe rytuały ochronne: krople krwi wrzucane do studni, dary zostawiane na placu, obrzędy w kaplicy. Wszystko to miało pierwotnie wzmacniać kontrolę nad pieczęcią, ale z biegiem lat zostało zniekształcone i zaczęło bardziej karmić uwięzioną obecność niż ją wiązać."}','draft','admin','2026-05-29 11:03:21');
INSERT INTO adventure_hooks VALUES(22,8,'location','Kamienne Wzgórze (test)','Małe, ponure miasteczko zbudowane na starszych niż pamięć fundamentach. Nad dachami góruje popękana kaplica, a pośrodku placu stoi stara studnia, wokół której mieszkańcy zostawiają drobne dary ''na szczęście''.','central','{"key": "kamienne_wzgorze", "label": "Kamienne Wzgórze", "description": "Małe, ponure miasteczko zbudowane na starszych niż pamięć fundamentach. Nad dachami góruje popękana kaplica, a pośrodku placu stoi stara studnia, wokół której mieszkańcy zostawiają drobne dary ''na szczęście''.", "location_type": "macro", "biome": "city"}','promoted',200,'game_locations',0.0,0,'2026-05-29 11:45:00');
INSERT INTO adventure_hooks VALUES(23,8,'npc','Burmistrz Edrik Voss','Przywódca miasteczka, wyczerpany i coraz bardziej desperacki. Publicznie nawołuje do wybicia wampirów, prywatnie zaś panicznie boi się prawdy o tym, co jego przodkowie ukryli pod miastem.','major','{"key": "burmistrz_edrik_voss", "label": "Burmistrz Edrik Voss", "npc_type": "quest_giver", "description": "Przywódca miasteczka, wyczerpany i coraz bardziej desperacki. Publicznie nawołuje do wybicia wampirów, prywatnie zaś panicznie boi się prawdy o tym, co jego przodkowie ukryli pod miastem.", "personality_prompt": "Lokalny przywódca i obrońca ludzi w oczach tłumu. Mówi stanowczo, lecz zdradza oznaki zmęczenia i narastającej paniki. Ukrywa księgę rodową opisującą dawne rytuały i część paktu. Chce ocalić miasteczko bez ujawniania winy własnego rodu."}','promoted',1024,'npcs',0.0,0,'2026-05-29 11:45:00');
INSERT INTO adventure_hooks VALUES(24,8,'npc','Matka Ilse','Starsza opiekunka kaplicy, surowa i pobożna. Uważa wampiry za narzędzie kary, ale zna stare modlitwy, które są w rzeczywistości zniekształconymi formułami pieczęci.','major','{"key": "matka_ilse", "label": "Matka Ilse", "npc_type": "quest_giver", "description": "Starsza opiekunka kaplicy, surowa i pobożna. Uważa wampiry za narzędzie kary, ale zna stare modlitwy, które są w rzeczywistości zniekształconymi formułami pieczęci.", "personality_prompt": "Surowa, pobożna i pełna religijnej pewności. Jest autorytetem duchowym, lecz nie rozumie pełnego sensu obrzędów, które odprawia od lat. Może naprowadzić na kryptę albo nieświadomie przyspieszyć katastrofę."}','pending',NULL,NULL,0.0,0,'2026-05-29 11:45:00');
INSERT INTO adventure_hooks VALUES(25,8,'npc','Lady Mirena','Przywódczyni kręgu wampirów, dawna szlachcianka związana z miejscem od stuleci. Wyniszczona długą strażą, chłodna w obyciu, ale autentycznie oddana ochronie ludzi, którzy jej nienawidzą.','central','{"key": "lady_mirena", "label": "Lady Mirena", "npc_type": "ally", "description": "Przywódczyni kręgu wampirów, dawna szlachcianka związana z miejscem od stuleci. Wyniszczona długą strażą, chłodna w obyciu, ale autentycznie oddana ochronie ludzi, którzy jej nienawidzą.", "personality_prompt": "Groźna, smutna i dumna wampirza strażniczka. Mówi chłodno i oszczędnie, lecz działa z autentycznej troski o ludzi. Chce utrzymać pieczęć i ocalić tyle istnień, ile się da. Żywi się rzadko i w kontrolowany sposób, czasem na ochotnikach z dawnych rodów."}','pending',NULL,NULL,0.0,0,'2026-05-29 11:45:00');
INSERT INTO adventure_hooks VALUES(27,8,'npc','Hagen Rupp','Miejscowy rzeźnik i herszt najbardziej agresywnej części tłumu. Stracił żonę podczas jednego z nocnych incydentów i pragnie zemsty, nieważne na kim.','major','{"key": "hagen_rupp", "label": "Hagen Rupp", "npc_type": "neutral", "description": "Miejscowy rzeźnik i herszt najbardziej agresywnej części tłumu. Stracił żonę podczas jednego z nocnych incydentów i pragnie zemsty, nieważne na kim.", "personality_prompt": "Porywczy, brutalny i napędzany żałobą. Jest przywódcą tłumu i szuka zemsty, by odzyskać poczucie kontroli. Nie dopuszcza do siebie myśli, że jego żona była już częściowo skażona wpływem bytu spod miasta."}','pending',NULL,NULL,0.0,0,'2026-05-29 11:45:00');
INSERT INTO adventure_hooks VALUES(28,8,'enemy','To, Co Tętni Pod Miastem','Starożytna obecność uwięziona pod Kamiennym Wzgórzem, być może pozostałość po przedludzkim kulcie, może larwalny demon, a może bezimienny byt z głębi ziemi. Nie ma jednej formy — objawia się przez pulsującą ziemię, krew, szał, mutacje i sny.','central','{"key": "to_co_tetni_pod_miastem", "label": "To, Co Tętni Pod Miastem", "hp_base": 60, "ac_base": 14, "attack_bonus": 6, "damage_die": "1d10", "description": "Starożytna obecność uwięziona pod Kamiennym Wzgórzem, być może pozostałość po przedludzkim kulcie, może larwalny demon, a może bezimienny byt z głębi ziemi. Nie ma jednej formy — objawia się przez pulsującą ziemię, krew, szał, mutacje i sny.", "tier": "boss", "damage_type": "physical", "encounter": {"title": "To, Co Tętni Pod Miastem", "scene_setup": "Pod Kamiennym Wzgórzem ziemia pulsuje jak żywe ciało, a w starych kryptach i kanałach pojawiają się smugi krwi, czarne narośla i ludzie doprowadzeni do szału przez wspólne sny. Im głębiej schodzą bohaterowie, tym wyraźniej ściany „oddychają”, a drżenie gruntu układa się w rytm potężnego serca. W centralnej komorze coś bezkształtnego przebija się przez kamień, jakby całe wzgórze próbowało urodzić własnego boga.", "trigger_condition": "Spotkanie rozpoczyna się, gdy bohaterowie badają zniknięcia, drgania gruntu lub krwawe incydenty wokół Kamiennego Wzgórza, albo gdy podążają za snem o sercu bijącym pod miastem.", "enemies": [{"name": "Awatar Tętniącej Obecności", "count": 1, "notes": "Boss; HP 60, AC 14, atak +6, obrażenia 1k10 fizyczne. Manifestuje się jako masa kamienia, krwi i kości wyrastająca ze ścian i podłoża; co 2 rundy zmienia kształt, zyskując narracyjnie zasięg, taran albo macki bez zmiany statystyk. Co turę komora reaguje na jego puls: osuwający się gruz, falująca posadzka lub krwawy wytrysk mogą wymusić ruch albo test równowagi według systemu."}, {"name": "Opętany Kultysta Wzgórza", "count": 2, "notes": "Dawni mieszkańcy, strażnicy lub robotnicy porwani przez sny. Walczą chaotycznie i osłaniają awatar, ale między napadami szału mogą błagać o pomoc; obezwładnieni zamiast zabici mają szansę odzyskać zmysły po zamknięciu lub zniszczeniu manifestacji."}], "objectives": ["Dotrzeć do komory pod Kamiennym Wzgórzem i przetrwać manifestację obecności.", "Pokonać Awatar Tętniącej Obecności albo odprawić rytuał pieczętujący przy użyciu starych znaków, soli, ognia lub święconej wody.", "Opcjonalnie uratować opętanych kultystów, obezwładniając ich zamiast zabijać."], "rewards": {"xp_estimate": 350, "loot_notes": "W komorze znajdują się relikty przedludzkiego kultu, kosztowności po zaginionych, notatki prowadzące do dalszej tajemnicy oraz dziwny kamień pulsujący słabym ciepłem. Jeśli bohaterowie zamkną szczelinę bez zawalenia tuneli, zyskują wdzięczność mieszkańców i dostęp do lokalnych katakumb, archiwów lub ukrytych przejść."}, "gm_notes": "To samowystarczalna mini-przygoda w tonie miejskiego horroru lub podziemnego boss-fightu. Zacznij od śledztwa w mieście (1-2 sceny: świadkowie snów, miejsce zbrodni, zaginiony wracający odmieniony), potem poprowadź drużynę przez pęknięte tunele do komory finałowej. Komora powinna być aktywnym zagrożeniem środowiskowym: ściany oddychają, krew sączy się z fug, grunt faluje przy mocniejszych ciosach awatara. Jeśli gracze wolą rozwiązanie rytualne, pozwól im zamknąć byt po wykonaniu 2-3 znaczących działań fabularnych pod presją walki, np. odtworzeniu znaków, rozrzuceniu soli i podpaleniu narośli. Po pokonaniu awatara możesz zostawić bijące jądro jako haczyk na przyszłość albo moralny wybór: zniszczyć je, zbadać czy ukryć."}}','approved',NULL,NULL,0.0,0,'2026-05-29 11:45:00');
INSERT INTO adventure_hooks VALUES(29,8,'location','Krypta Pieczęci','Ukryta komora pod kaplicą i studnią, gdzie stare kamienie są popękane od wewnętrznego nacisku. Na ścianach widnieją ślady dawnych rytuałów ochronnych i krwawych ofiar.','central','{"key": "krypta_pieczeci", "label": "Krypta Pieczęci", "description": "Ukryta komora pod kaplicą i studnią, gdzie stare kamienie są popękane od wewnętrznego nacisku. Na ścianach widnieją ślady dawnych rytuałów ochronnych i krwawych ofiar.", "location_type": "dungeon", "biome": "dungeon", "encounter": {"title": "Krypta Pieczęci", "scene_setup": "Pod zrujnowaną kaplicą, za wyschniętą studnią, kryje się pęknięta krypta, której ściany noszą ślady ochronnych sigili i zaschniętej krwi ofiar. Kamienie wybrzuszają się od środka, jakby coś od lat napierało na pieczęć, a w powietrzu unosi się metaliczny zapach i cichy pulsujący szmer. Gdy intruzi naruszą centralny krąg, uwięziona moc budzi strażników i zaczyna rozrywać komorę od wewnątrz.", "trigger_condition": "Spotkanie rozpoczyna się, gdy bohaterowie otworzą zejście pod kaplicą, zbadają rytualne znaki lub wejdą do centralnej komory krypty.", "enemies": [{"name": "Strażnik Pieczęci", "count": 1, "notes": "Opancerzony nieumarły kapłan lub kamienny strażnik związany z rytuałem; broni centralnego kręgu i próbuje odepchnąć intruzów od pieczęci."}, {"name": "Krwawe Cienie Ofiar", "count": 2, "notes": "Widmowe pozostałości dawnych ofiar; pojawiają się przy naruszeniu sigili, osłabiają odwagę i próbują wciągnąć żywych w krwawe ślady na posadzce."}], "objectives": ["Przetrwać starcie i ustalić, co napiera na pieczęć od środka.", "Ustabilizować lub świadomie zerwać pieczęć poprzez rytuał, zniszczenie sigili albo poświęcenie cennego zasobu.", "Wydostać się z krypty, zanim pękające ściany i uwolniona energia zawalą komorę."], "rewards": {"xp_estimate": 75, "loot_notes": "Rytualny amulet ochronny, księga dawnych egzorcyzmów, fiolka poświęconej krwi lub fragment pieczęci działający jako jednorazowy talizman przeciw nieumarłym i bytom z otchłani."}, "gm_notes": "To spotkanie działa jako krótki dungeon-room z wyborem moralnym: utrzymać pieczęć i zostawić zagrożenie uwięzione, albo ją złamać, by zdobyć wiedzę lub skarb kosztem uwolnienia czegoś gorszego poza kadr mini-przygody. Jeśli drużyna lubi śledztwo, dodaj wskazówki, że dawne ofiary były dobrowolne i miały powstrzymać istotę pod kryptą; jeśli wolisz akcję, potraktuj drżenie ścian jako licznik czasu rosnący co rundę. Poziom trudności łatwo skalować: Strażnik może być elitarnym przeciwnikiem solo albo słabszym obrońcą wspieranym przez bardziej agresywne cienie."}}','approved',NULL,NULL,0.0,0,'2026-05-29 11:45:00');
INSERT INTO campaign_templates VALUES(6,'Mgły nad drogą do ruin (test)','W mrocznych górach, gdzie mgły duszą drogi, a stare klątwy nie chcą umrzeć, czeka Zamek Drachenfels — miejsce, którego lepiej nie budzić ze snu. Plotki o zaginionych, tajemniczych światłach i zakazanym dziedzictwie szybko wciągną cię w śledztwo, w którym każdy krok może kosztować więcej niż życie. To opowieść o strachu, pokusie i wyborach, które zostawiają blizny głębsze niż rany.',2,'','{"title": "Mgły nad drogą do ruin (test)", "premise": "W mrocznych górach, gdzie mgły i stare klątwy mieszają się z ludzką chciwością, bohaterowie zostają wciągnięci w sprawę zamku Drachenfels — ruin, które ponoć nigdy nie powinny zostać odbudzone ani przebudzone. Plotki o zaginionych, dziwnych światłach nad twierdzą i sekretnym dziedzictwie dawnego rodu prowadzą do śledztwa, które szybko okazuje się walką nie tylko z potworami, ale też z własnymi kompromisami moralnymi.", "acts": [{"number": 1, "title": "Mgły nad drogą do ruin (edit test)", "summary": "Bohaterowie trafiają do podnóża Drachenfels, gdzie znikają podróżni, a miejscowi unikają rozmów o zamku. Pierwsze ślady wskazują, że ktoś lub coś aktywnie bada ruiny i sprowadza do okolicy śmierć oraz obłęd.", "key_beats": ["Przybycie do ponurej karczmy i zebranie plotek o zniknięciach", "Pierwsze starcie z napastnikami lub potwornymi zwiadowcami w ruinach drogi", "Odnalezienie symbolu starego rodu Drachenfels i tropu prowadzącego do starej kaplicy"], "completed": false}, {"number": 2, "title": "Karczma pod Złamanym Rogiem", "summary": "Śledztwo wśród przestraszonych wieśniaków i w karczmie ujawnia, że ktoś kupuje relikwie, mapy i stare zapisy o zamku. Bohaterowie odkrywają sieć kłamstw, a jeden z mieszkańców może być bardziej winny, niż wygląda.", "key_beats": ["Przesłuchanie świadków i zdobycie informacji o tajemniczym patronie", "Odkrycie ukrytego schowka z dokumentami lub artefaktem", "Moralny wybór: ujawnić winnego tłumowi czy wykorzystać go jako źródło wiedzy"], "completed": false}, {"number": 3, "title": "Kaplica bez dzwonu", "summary": "W starej kaplicy pod zamkiem bohaterowie znajdują ślady dawnego rytuału, który miał zamknąć coś w podziemiach Drachenfels. Im więcej odkrywają, tym wyraźniej widać, że pieczęć została naruszona, a ktoś celowo ją osłabia.", "key_beats": ["Wejście do kaplicy i konfrontacja z nieumarłymi strażnikami", "Odszyfrowanie inskrypcji o krwi, dziedziczeniu i cenie za otwarcie wrót", "Pozyskanie klucza rytualnego lub fragmentu pieczęci"], "completed": false}, {"number": 4, "title": "Schody do wnętrza góry", "summary": "Droga do zamku prowadzi przez zdradliwe przejścia, zawalone tunele i miejsca, gdzie ściany zdają się szeptać. Na bohaterów polują słudzy ukrytej siły, a każdy krok bliżej serca góry ujawnia nowe okrucieństwa dawnych właścicieli.", "key_beats": ["Eksploracja podziemnych korytarzy i pułapek obronnych zamku", "Spotkanie z ocalałym lub zdeprawowanym sługą rodu Drachenfels", "Zdobycie dostępu do głównego dziedzińca albo sekretnego przejścia do lochów"], "completed": false}, {"number": 5, "title": "Dziedzic krwi i popiołu", "summary": "W zamku okazuje się, że ktoś rości sobie prawo do Drachenfels, powołując się na krew, proroctwo lub dawne zobowiązanie. Bohaterowie muszą zdecydować, czy zniszczyć rodowe dziedzictwo, czy wykorzystać je przeciw większemu złu.", "key_beats": ["Rozmowa lub konfrontacja z dziedzicem rodu albo jego wysłannikiem", "Ujawnienie prawdziwego celu odbudowy zamku", "Wybór sojuszu, szantażu albo otwartego przecięcia więzi z rodem"], "completed": false}, {"number": 6, "title": "Komnata pod wieżą", "summary": "W sercu zamku znajduje się komnata rytualna, gdzie splatają się magia, krew i pamięć dawnych zbrodni. Bohaterowie odkrywają, że zagrożenie nie jest jedynie fizyczne — to także pokusa władzy i obietnica zakończenia cierpienia za cenę potępienia.", "key_beats": ["Przejście przez ostatnią linię obrony i strażników rytuału", "Ujawnienie prawdy o tym, co naprawdę uwięziono w zamku", "Próba przerwania, przejęcia albo wypaczenia ceremonii"], "completed": false}, {"number": 7, "title": "Upadek albo dziedzictwo", "summary": "Finał rozstrzyga, czy Drachenfels zostanie oczyszczony, czy stanie się narzędziem nowej potęgi. Nawet zwycięstwo może okazać się skażone, bo nie każda klątwa kończy się wraz ze śmiercią potwora.", "key_beats": ["Ostateczna walka w sercu zamku i rozpad dawnych zabezpieczeń", "Decyzja o zniszczeniu, przejęciu lub zapieczętowaniu źródła zła", "Epilog pokazujący cenę podjętych wyborów i nowe plotki o ruinach"], "completed": false}], "endings": [{"id": "ending_primary", "title": "Oczyszczenie ruin", "type": "primary", "description": "Bohaterowie niszczą rytualne źródło skażenia i zamykają Drachenfels, lecz przy okazji bezpowrotnie grzebią wiedzę, która mogła ocalić innych. Zamek staje się grobowcem zła, ale także miejscem, gdzie zginęły szanse na lepsze rozwiązanie.", "requirements": ["Źródło klątwy zostaje zniszczone lub unieszkodliwione", "Bohaterowie nie oddają zamku w ręce dziedzica ani kultu"]}, {"id": "ending_alternate", "title": "Dziedzictwo w cudzych dłoniach", "type": "alternate", "description": "Bohaterowie powstrzymują największe zagrożenie, ale pozwalają, by zamek lub jego sekret przejęła frakcja gotowa użyć go do własnych celów. Świat zostaje uratowany tylko częściowo, a nad ruinami zaczyna rosnąć nowe, równie mroczne panowanie.", "requirements": ["Bohaterowie zawierają układ z dziedzicem, kultem albo lokalnym możnowładcą"]}], "key_npcs": [{"key": "herr_emmerich", "name": "Herr Emmerich von Kalt", "role": "zgryźliwy zarządca okolicznych ziem i pośredni patron śledztwa", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów oszczędnie, jak człowiek, który zawsze coś ukrywa i boi się, że każdy gest zdradzi jego winę.", "description": "Zamożny, wychudzony szlachcic z twarzą pooraną zmęczeniem i zimnym spojrzeniem człowieka, który zbyt długo negocjował z rzeczami nie do negocjacji. Oficjalnie chce spokoju w okolicy, nieoficjalnie pragnie odzyskać wpływy nad tym, co drzemie w Drachenfels.", "keyword_triggers": ["zamek", "pieczęć", "dziedzic", "zniknięcia"]}, {"key": "greta_schwarz", "name": "Greta Schwarz", "role": "karczmarka i cicha zbieraczka plotek", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Bądź praktyczna, podejrzliwa i serdeczna tylko wtedy, gdy ktoś zasłużył na odrobinę zaufania.", "description": "Krępa kobieta o spracowanych dłoniach i spojrzeniu, które waży każde słowo. Jej karczma jest centrum wiejskich plotek, a ona sama wie więcej o zniknięciach niż początkowo przyznaje.", "keyword_triggers": ["karczma", "zniknęli", "nocą", "obcy"]}, {"key": "albrecht_drachenfels", "name": "Albrecht Drachenfels", "role": "ostatni dziedzic rodu lub jego skażony reprezentant", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów z arystokratyczną dumą, ale pozwól, by pod spodem brzmiał głód uznania i lęk przed utratą znaczenia.", "description": "Blady mężczyzna o eleganckich manierach i oczach, w których widać zarówno inteligencję, jak i obłęd. Uważa, że tylko on ma prawo decydować o losie zamku, nawet jeśli oznacza to poświęcenie innych.", "keyword_triggers": ["dziedzictwo", "krew", "prawo", "rodzina"]}, {"key": "sister_ildrun", "name": "Siostra Ildrun", "role": "zakonnica-archiwistka strzegąca zakazanych zapisów", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów jak osoba wierząca, lecz zmęczona grzechami świata i gotowa na kompromis z sumieniem.", "description": "Chuda zakonnica z zaciśniętymi ustami i rękami wiecznie ubrudzonymi od starych ksiąg. Zna dawne rytuały związane z Drachenfels i wie, że prawda może być równie niebezpieczna jak kłamstwo.", "keyword_triggers": ["archiwum", "rytuał", "pieczęć", "grzech"]}, {"key": "konrad_weiss", "name": "Konrad Weiss", "role": "łowca nagród i oportunista", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów lekko, z ironią, jak ktoś, kto zawsze szuka zysku, ale nie jest całkiem odporny na strach.", "description": "Szorstki najemnik w przetartej skórze, z twarzą człowieka, który przeżył za dużo bitew, by wierzyć w honor. Może pomóc bohaterom, jeśli uzna, że bardziej opłaca mu się żywi niż martwi.", "keyword_triggers": ["nagroda", "szlak", "ruiny", "zapłata"]}], "key_locations": [{"key": "karczma_pod_zlamanym_rogiem", "name": "Karczma pod Złamanym Rogiem", "role": "punkt startowy", "description": "Przydrożna karczma stoi na skraju cywilizacji, gdzie błoto, deszcz i strach tworzą jedną, lepką całość. W środku panuje ciężka atmosfera, a rozmowy milką, gdy tylko pada nazwa Drachenfels. To miejsce służy jako pierwsze źródło plotek, drobnych sojuszy i zdradliwych półprawd.", "visited": false}, {"key": "ruiny_kaplicy", "name": "Ruiny Kaplicy Św. Ostatniego Światła", "role": "miejsce śledztwa i rytuału", "description": "Stara kaplica stoi krzywo na zboczu, jakby sama ziemia próbowała ją wyrzucić. Wewnątrz czuć wilgoć, kadzidło i coś znacznie gorszego — zapach dawno odprawionych modlitw, które nie zostały wysłuchane. To miejsce skrywa wskazówki do pieczęci i dowody na dawne zbrodnie.", "visited": false}, {"key": "zamek_drachenfels", "name": "Zamek Drachenfels", "role": "główna twierdza i finał kampanii", "description": "Ruina zamku góruje nad okolicą niczym wyrzut sumienia wykuty w kamieniu. Jego mury są popękane, lecz nadal emanują groźbą, a w korytarzach słychać echo dawnych krzyków i nowych szeptów. To serce kampanii, miejsce zdrady, rytuału i ostatecznego wyboru.", "visited": false}, {"key": "podziemia_drachenfels", "name": "Podziemia Drachenfels", "role": "labirynt sekretów i więzienie klątwy", "description": "Pod zamkiem ciągną się ciasne, duszne korytarze, gdzie woda kapie jak odliczanie do śmierci. Ściany pokrywają stare znaki, a w niszach kryją się kości, mechanizmy i rzeczy, których lepiej nie nazywać. To tutaj najłatwiej zgubić drogę, rozsądek i duszę.", "visited": false}], "key_enemies": [{"key": "upiorny_straznik", "name": "Upiorny Strażnik Drachenfels", "role": "", "tier": "standard", "description": "Przezroczysty wojownik w zardzewiałej zbroi, którego twarz jest ledwie widocznym wspomnieniem człowieka. Porusza się bezszelestnie i reaguje na naruszenie dawnych granic jak pies na krzywdę pana.", "note": "Ignoruje część obrażeń niemagicznych i atakuje przede wszystkim intruzów łamiących pieczęcie. Walczy defensywnie, próbując odciąć drogę odwrotu i zmusić ofiary do paniki.", "count": 1, "hp_base": 22, "ac_base": 13, "damage_die": "1d6"}, {"key": "skażony_ghoul", "name": "Skażony Ghoul z Lochu", "role": "", "tier": "standard", "description": "Wychudzone, zgarbione stworzenie o błyszczących oczach i zębach czarnych od starej krwi. Pachnie wilgocią grobu i ludzkim mięsem, a jego ruchy są szybkie i nieludzkie.", "note": "Poluje w grupie, atakuje z flanki i rozrywa samotnych przeciwników. Potrafi wspinać się po murach i przeciskać przez szczeliny, co czyni go groźnym w ciasnych korytarzach.", "count": 1, "hp_base": 18, "ac_base": 12, "damage_die": "1d6"}, {"key": "rytualny_kultysta", "name": "Rytualny Kultysta Cienia", "role": "", "tier": "standard", "description": "Oszalały wyznawca w brudnym kapturze, z rękami poplamionymi atramentem, krwią i popiołem. Jego twarz zdradza fanatyzm człowieka, który uznał potępienie za ścieżkę do zbawienia.", "note": "Wspiera innych zaklęciami, zakłóceniami i ofiarami z własnej krwi. Najgroźniejszy, gdy ma czas na przygotowanie rytuału lub wezwanie posiłków.", "count": 1, "hp_base": 16, "ac_base": 11, "damage_die": "1d6"}], "active_act": 1, "scene_log": [], "deviations": [], "branches": [], "engine_private": {"secret_predisposition_hint": "Najbezpieczniejszą drogą do zwycięstwa jest współpraca z kimś, kto ma najwięcej do ukrycia; prawda o zamek jest mniej ważna niż to, kto pierwszy ją wykorzysta.", "hidden_twist": "Źródłem klątwy nie jest sam zamek, lecz pieczęć podtrzymywana przez krew rodu Drachenfels — jej zerwanie uwalnia zarówno potworność, jak i wiedzę o dawnym pakcie.", "contingency": "Jeśli bohaterowie ominą śledztwo, niech zamek sam zacznie działać przeciw nim: pojawiają się fałszywe tropy, nocne zjawy i ofiary, które prowadzą ich dokładnie tam, gdzie chce ukryta siła."}, "key_items": []}','[9, 10, 11, 13, 14, 15, 16]','draft',0,'admin','2026-05-27 21:30:18',NULL,NULL,NULL);
INSERT INTO campaign_templates VALUES(8,'Cienie Zagubionych Królestw','Eksploracja starożytnych ruin Valdorii, walka z klątwą i poszukiwanie siedmiu Pieczęci Zapomnianego Króla',3,'Mroczne ruiny pełne niebezpieczeństw, duchy przeszłości i zagadki starożytnej magii','{"title": "Cienie Zagubionych Królestw", "premise": "Wyprawa w mroczne ruiny Valdorii prowadzi drużynę przez miejsca nasiąknięte starożytną magią, duchami dawnych władców i rosnącą klątwą, która budzi się wraz z poszukiwaniem siedmiu Pieczęci Zapomnianego Króla. Każda zdobyta pieczęć przybliża bohaterów do prawdy o upadku królestwa, ale także do przebudzenia siły, która nie powinna ujrzeć światła dnia.", "acts": [{"number": 1, "title": "Wejście do popiołów Valdorii", "summary": "Bohaterowie docierają do pierwszych ruin i poznają ciężar klątwy, która spowija dawne granice królestwa. Trop prowadzi ich do pierwszej pieczęci, ale już sam początek wyprawy ujawnia, że ktoś inny śledzi te same artefakty.", "key_beats": ["Przybycie do zrujnowanego pogranicza i pierwsze zetknięcie z duchami poległych strażników", "Odnalezienie śladów pierwszej Pieczęci w zapadniętej kaplicy i walka z jej strażnikiem", "Poznanie rywala lub patrona, który zna więcej o Valdorii, niż powinien"], "completed": false}, {"number": 2, "title": "Szept w kamiennych korytarzach", "summary": "W podziemiach i ruinach miasta bohaterowie odkrywają sieć starych przejść, z których każde skrywa fragment historii o upadku króla. Druga i trzecia pieczęć są ukryte za zagadkami, lecz rozwiązania mają cenę w postaci krwi, wspomnień albo zaufania.", "key_beats": ["Eksploracja podziemnych krypt i odnalezienie śladów rytuału, który rozdarł królestwo", "Rozwiązanie starożytnej zagadki wymagającej poświęcenia zasobów lub ujawnienia sekretu", "Konfrontacja z pierwszym poważnym przeciwnikiem, który próbuje przejąć pieczęci siłą"], "completed": false}, {"number": 3, "title": "Dwór bez króla", "summary": "Drużyna trafia do dawnej sali tronowej, gdzie zjawiska nadnaturalne odtwarzają ostatnie dni Valdorii. Prawda o Zapomnianym Królu okazuje się bardziej niepokojąca niż legenda, a sojusze zaczynają pękać pod ciężarem tego odkrycia.", "key_beats": ["Wejście do nawiedzonego centrum dawnej władzy i obserwacja zjawy dworu", "Odkrycie, że pieczęci nie tylko chronią, ale także więżą coś głębiej ukrytego", "Moralny wybór dotyczący zaufania do jednego z kluczowych NPC"], "completed": false}, {"number": 4, "title": "Krąg siedmiu znaków", "summary": "Zebrane pieczęci prowadzą do rytualnego kręgu, gdzie można odwrócić klątwę albo ją dopełnić. Bohaterowie muszą zdecydować, czy zniszczyć artefakty, użyć ich do zamknięcia przebudzonej siły, czy spróbować przejąć władzę nad dawną magią.", "key_beats": ["Dotarcie do rytualnego miejsca i przygotowanie ceremonii pod presją czasu", "Atak sił klątwy oraz zdrada albo desperacka próba przejęcia pieczęci", "Ujawnienie pełnej prawdy o tym, co naprawdę spoczywa pod Valdorią"], "completed": false}, {"number": 5, "title": "Korona z cienia", "summary": "Finał rozgrywa się przy sercu ruin, gdzie przebudzona moc żąda nowego władcy lub nowego więzienia. Bohaterowie stają przed wyborem, który może ocalić ocalałe resztki Valdorii albo skazać je na jeszcze gorszy los, niż miały dotąd.", "key_beats": ["Ostateczne starcie z głównym strażnikiem klątwy i jego sługami", "Decyzja o losie siedmiu Pieczęci oraz o tym, kto ma prawo użyć ich mocy", "Domknięcie wyprawy z konsekwencjami, które zmienią przyszłość regionu"], "completed": false}], "endings": [{"id": "ending_primary", "title": "Pieczęcie zamknięte, królestwo pogrzebane", "type": "primary", "description": "Bohaterowie zamykają przebudzoną siłę i odwracają klątwę, ale tylko częściowo: Valdoria pozostaje ruiną, a wraz z pieczęciami ginie ostatnia szansa na odrodzenie dawnej potęgi. Ocalały świat jest bezpieczniejszy, lecz cena to utrata wiedzy, skarbów i być może prawdy o tym, co należało ocalić.", "requirements": ["Zebrać co najmniej sześć z siedmiu Pieczęci Zapomnianego Króla", "Podjąć decyzję o zamknięciu mocy zamiast jej przejęcia"]}, {"id": "ending_alternate", "title": "Korona dla żywych", "type": "alternate", "description": "Bohaterowie używają pieczęci, by przejąć kontrolę nad dawną magią i narzucić jej nowy porządek. Klątwa słabnie, ale nie znika całkowicie, a ci, którzy sięgnęli po władzę, stają się strażnikami lub więźniami tego, co obudzili.", "requirements": ["Odnaleźć wszystkie siedem Pieczęci", "Przyjąć ryzyko wykorzystania mocy zamiast jej zniszczenia"]}], "key_npcs": [{"key": "archiwistka_elwena", "name": "Archiwistka Elwena", "role": "uczona i strażniczka urwanych kronik Valdorii", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów spokojnie, z wyraźną obsesją na punkcie porządku i faktów, ale pozwól, by pod powierzchnią przebijał strach przed tym, co może znaleźć drużyna.", "description": "Ostatnia żyjąca badaczka dawnych kronik, nosząca przy sobie poplamione mapy i zniszczone księgi. Zna legendę o Pieczęciach, lecz ukrywa, że część wiedzy zdobyła w sposób nie do końca uczciwy.", "keyword_triggers": ["pieczęć", "valdoria", "kronika", "król", "rytuał"]}, {"key": "kapitan_dorn", "name": "Kapitan Dorn", "role": "najemnik i przewodnik po ruinach", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Bądź szorstki, pragmatyczny i niechętny do heroizmu; pokaż człowieka, który widział zbyt wiele i wierzy tylko w to, co da się sprzedać albo przeżyć.", "description": "Doświadczony przewodnik wynajęty do przeprowadzenia drużyny przez zdradliwe rejony ruin. Zna bezpieczne ścieżki, ale jego lojalność zależy od korzyści i od tego, kto wydaje się silniejszy.", "keyword_triggers": ["droga", "ruiny", "zaplata", "straż", "przeżyć"]}, {"key": "siostra_maela", "name": "Siostra Maela", "role": "kapłanka próbująca oczyścić klątwę", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów z cichą determinacją i współczuciem, ale nie bój się fanatycznej nuty, gdy rozmowa schodzi na grzech, ofiarę i odkupienie.", "description": "Wędrowna kapłanka, która uważa Valdorię za miejsce świętokradztwa i cierpienia. Może stać się cennym sojusznikiem, ale równie łatwo popchnie drużynę do skrajnych decyzji.", "keyword_triggers": ["grzech", "oczyszczenie", "modlitwa", "ofiara", "duchy"]}, {"key": "lord_varek", "name": "Lord Varek", "role": "potomek upadłego rodu i pretendujący spadkobierca", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów jak ktoś, kto uważa się za naturalnego władcę, ale w chwilach nacisku pozwól, by pojawiała się w nim desperacja i lęk przed zapomnieniem.", "description": "Arystokrata roszczący sobie prawo do ruin Valdorii i tajemnic Pieczęci. Pragnie przywrócić znaczenie swojemu rodowi, nawet jeśli oznacza to użycie niebezpiecznej mocy.", "keyword_triggers": ["dziedzictwo", "korona", "prawo", "ród", "władza"]}, {"key": "maska_z_popiolu", "name": "Maska z Popiołu", "role": "tajemniczy pośrednik dawnych sił", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów zagadkami, półprawdami i sugestiami, jak ktoś, kto zawsze wie trochę więcej, niż ujawnia, i czerpie przyjemność z cudzych wątpliwości.", "description": "Istota lub człowiek ukrywający twarz pod popielatą maską, pojawiający się tam, gdzie pieczęci zmieniają właściciela. Może pomagać drużynie, ale jego intencje są nieprzejrzyste i prawdopodobnie związane z przebudzeniem dawnego króla.", "keyword_triggers": ["maska", "popiół", "sekret", "pieczęć", "sługa"]}], "key_locations": [{"key": "zawalona_brama_valdorii", "name": "Zawalona Brama Valdorii", "role": "punkt startowy", "description": "Rozpadnięta brama stanowi wejście do dawnego królestwa i pierwsze miejsce, gdzie czuć chłód klątwy. Kamienne lwy są połamane, a w szczelinach murów gnieżdżą się cienie, które reagują na obecność żywych. To tutaj drużyna po raz pierwszy zrozumie, że ruiny nie są martwe.", "visited": false}, {"key": "krypta_siedmiu_pieczeci", "name": "Krypta Siedmiu Pieczęci", "role": "podziemne sanktuarium", "description": "Podziemna krypta skrywa fragmenty kronik, rytualne misy i miejsca spoczynku pierwszych strażników pieczęci. Powietrze jest tu ciężkie od wilgoci i kadzidła, a ściany pokrywają napisy, które zmieniają znaczenie przy blasku świec. To miejsce służy zarówno jako łamigłówka, jak i próba dla tych, którzy chcą sięgnąć po zakazaną wiedzę.", "visited": false}, {"key": "dwor_zapomnianego_krola", "name": "Dwór Zapomnianego Króla", "role": "nawiedzona sala tronowa", "description": "Zrujnowany dwór wciąż odtwarza echa dawnej potęgi: słychać kroki dworzan, brzęk srebra i odległy głos wydający nieistniejące rozkazy. Sala tronowa jest pęknięta jak rozbite zwierciadło, a każdy krok budzi wspomnienia, które mogą zaatakować umysł równie skutecznie jak miecz. To serce tragedii Valdorii i miejsce, gdzie prawda staje się niebezpieczna.", "visited": false}, {"key": "krag_siedmiu_znakow", "name": "Krąg Siedmiu Znaków", "role": "miejsce rytuału finałowego", "description": "Kamienny krąg stoi na szczycie wzgórza nad ruinami, otoczony poszarpanymi obeliski i spękaną ziemią. W nocy znaki w kamieniu jarzą się bladym światłem, jakby sama ziemia pamiętała rytuał sprzed wieków. To tutaj można rozstrzygnąć los klątwy, ale każda decyzja będzie miała cenę w krwi lub duszy.", "visited": false}], "key_enemies": [{"key": "duch_straznika", "name": "Duch Strażnika", "role": "", "tier": "standard", "description": "Przezroczysty wojownik w pordzewiałej zbroi, z twarzą zniekształconą gniewem i wiecznym obowiązkiem. Porusza się sztywno, jakby wciąż wykonywał rozkazy dawno umarłego pana.", "note": "Ignoruje część zwykłej broni niemagicznej i atakuje tych, którzy naruszają miejsca pieczęci. Najlepiej działa przeciw niemu światło, rytuały ochronne i rozproszenie jego obowiązku przez ujawnienie prawdy o jego śmierci.", "count": 1, "hp_base": 18, "ac_base": 12, "damage_die": "1d6"}, {"key": "nekromanta_z_kurhanu", "name": "Nekromanta z Kurhanu", "role": "", "tier": "elite", "description": "Wysoki, wychudzony mag w zbutwiałych szatach, z palcami umazanymi popiołem i kośćmi. Jego głos brzmi jak szept z grobu, a oczy świecą bladą, chorą zielenią.", "note": "Wskrzesza poległych jako słabych sług i korzysta z terenu, by rozdzielać drużynę. Walczy zza osłon, używa klątw osłabiających i ustawia się tak, by zmusić bohaterów do podejmowania trudnych wyborów.", "count": 1, "hp_base": 34, "ac_base": 14, "damage_die": "1d8"}, {"key": "cien_zapomnianego_krola", "name": "Cień Zapomnianego Króla", "role": "", "tier": "boss", "description": "Gigantyczna, nienaturalna sylwetka utkana z mroku, koron i pękniętych wspomnień o dawnym władcy. Nie ma jednej twarzy, tylko zmienne oblicza tych, którzy kiedyś mu służyli albo go zdradzili.", "note": "Zmienia formę między atakami, wykorzystuje strach i wspomnienia bohaterów oraz staje się silniejszy, gdy pieczęci są używane niezgodnie z przeznaczeniem. W walce preferuje łamanie morale, izolowanie celów i niszczenie źródeł światła.", "count": 1, "hp_base": 52, "ac_base": 15, "damage_die": "1d10"}], "active_act": 1, "scene_log": [], "deviations": [], "branches": [], "engine_private": {"secret_predisposition_hint": "Najsilniej na przebieg kampanii wpłynie to, czy drużyna zaufa archiwistce Elwenie, czy też kapitanowi Dornowi; obie ścieżki prowadzą do prawdy, ale przez inne ofiary.", "hidden_twist": "Zapomniany Król nie został jedynie pokonany ani uwięziony — został rozdzielony na siedem pieczęci, a każda zawiera część jego woli, przez co zbieranie artefaktów budzi jego świadomość.", "contingency": "Jeśli bohaterowie ominą jedną z pieczęci, można zastąpić ją echem rytuału lub odłamkiem korony, ale cena wzrośnie: klątwa nasili się, a finał stanie się bardziej desperacki i niebezpieczny."}}','[]','draft',0,'admin','2026-05-28 06:25:29',NULL,NULL,NULL);
INSERT INTO campaign_templates VALUES(9,'Klątwa Żelaznego Lasu','Żelazny Las nie szepcze — on pamięta, a jego pamięć bywa głodna. W tej mrocznej kampanii przemierzysz trakty spowite mgłą, wejdziesz między zwaśnionych możnych i odkryjesz, że pod korzeniami starych drzew pulsuje coś starszego niż ludzki grzech. Jeśli odważysz się zajrzeć w cień kaplicy pod czarnym dębem, możesz ocalić więcej niż własną skórę — albo przepaść razem z całym lasem.',4,'Eerie, oppressive, ancient','{"title": "Klątwa Żelaznego Lasu", "premise": "W Żelaznym Lesie, gdzie stare drzewa mają korzenie twarde jak żelazo, a noc niechętnie ustępuje świtu, zaczynają znikać ludzie, bydło i całe patrole leśnych straży. Miejscowi możni oskarżają się nawzajem o sabotaż, podczas gdy dawna magia budzi się spod mchów i popiołu. Drużyna zostaje wciągnięta w sieć politycznych intryg, paktów z pradawnymi siłami i klątwy, która może ocalić las albo skazać go na wieczne skarlenie.", "acts": [{"number": 1, "title": "Mgły nad traktami", "summary": "Bohaterowie trafiają do przygranicznej osady, gdzie zniknięcia, strach i wzajemne oskarżenia rozrywają wspólnotę. Pierwsze tropy prowadzą do lasu, ale równie ważne okazują się napięcia między lokalnym zarządcą, druidycznymi tradycjami i kupieckimi interesami. Akt kończy się odkryciem, że zaginięcia nie są przypadkowe, lecz związane z dawnym miejscem mocy.", "key_beats": ["Przybycie do osady spowitej mgłą i przesłuchanie świadków ostatnich zniknięć", "Pierwsze ślady prowadzące do granicy Żelaznego Lasu oraz spór o winę między frakcjami", "Odnalezienie starego znaku rytualnego, który wskazuje na obecność pradawnej klątwy"], "completed": false}, {"number": 2, "title": "Korzenie spisku", "summary": "Śledztwo ujawnia, że za strachem mieszkańców stoją nie tylko potwory, lecz także ludzie próbujący wykorzystać chaos. Bohaterowie odkrywają tajne układy między lokalnym zarządcą, handlarzami drewna i kimś związanym z dawną kaplicą w lesie. W miarę jak napięcie rośnie, drużyna musi zdecydować, komu zaufać, a komu odebrać władzę nad informacjami.", "key_beats": ["Przesłuchanie leśników, drwali i kupców ujawniające sprzeczne wersje wydarzeń", "Znalezienie ukrytego składu rytualnych przedmiotów i dokumentów obciążających jedną z frakcji", "Pierwsze starcie z nadnaturalnymi strażnikami lasu, którzy atakują tylko intruzów z konkretnym znakiem"], "completed": false}, {"number": 3, "title": "Kaplica pod czarnym dębem", "summary": "Drużyna dociera do zapomnianej kaplicy i jej podziemi, gdzie splatają się ślady dawnego kultu, wojennej zdrady i nieudanej próby uwięzienia leśnego ducha. W centrum tajemnicy leży rytuał podtrzymujący klątwę, a także osoba, która od lat manipuluje wydarzeniami, by utrzymać las w stanie kontrolowanego lęku. Akt ten obnaża prawdziwą skalę zagrożenia i pokazuje, że klątwa ma zarówno źródło magiczne, jak i polityczne.", "key_beats": ["Eksploracja kaplicy, krypt i bocznych komór pełnych dawnych ofiar i zakazanych symboli", "Odkrycie kroniki lub relikwii wyjaśniającej, że klątwa została celowo podtrzymana po dawnym konflikcie", "Konfrontacja z głównym manipulatorem lub jego wysłannikiem, który próbuje zatrzeć ślady"], "completed": false}, {"number": 4, "title": "Rada cieni", "summary": "Wiedza zdobyta w kaplicy wywołuje kryzys wśród lokalnych elit, a bohaterowie zostają zmuszeni do gry dyplomatycznej między strachem, zdradą i desperacją. Każda frakcja chce wykorzystać odkrycia drużyny do własnych celów: jedni pragną oczyścić las, inni go spalić, a jeszcze inni zamienić klątwę w narzędzie władzy. Akt rozgrywa się w cieniu narastającego ataku nadnaturalnych sił, który sprawia, że negocjacje stają się wyścigiem z czasem.", "key_beats": ["Spotkanie z lokalnymi możnymi i ujawnienie dowodów prowadzących do publicznego konfliktu", "Wybór sojuszu lub rozbicie układu, który dotąd utrzymywał kruchy porządek w osadzie", "Obrona osady przed nocnym uderzeniem potworów, które reagują na decyzje bohaterów"], "completed": false}, {"number": 5, "title": "Serce Żelaznego Lasu", "summary": "Ostateczna wyprawa prowadzi do najgłębszego, skażonego centrum lasu, gdzie źródło klątwy przybrało materialną formę. Bohaterowie muszą podjąć decyzję, czy zerwać pakt i uwolnić pradawną siłę, czy przejąć kontrolę nad nią kosztem moralnej ceny. Finał rozstrzyga nie tylko los lasu, lecz także przyszłość ludzi, którzy uczynili z niego pole walki o władzę.", "key_beats": ["Przejście przez martwy krąg drzew i pokonanie ostatnich strażników miejsca mocy", "Rytualna konfrontacja z istotą lub sercem klątwy, wymagająca wyborów fabularnych i ofiar", "Rozstrzygnięcie losu lasu, osady i tych, którzy przetrwali polityczną intrygę"], "completed": false}], "endings": [{"id": "ending_primary", "title": "Uciszenie lasu", "type": "primary", "description": "Bohaterowie zrywają klątwę, lecz cena jest wysoka: Żelazny Las traci część swojej dawnej siły, a wraz z nią giną sekrety, które chroniły go przed jeszcze gorszym złem. Osada ocala, ale staje się miejscem sporów o władzę, ziemię i pamięć o tych, którzy zginęli, by zakończyć cierpienie.", "requirements": ["Zniszczyć lub odwrócić rytuał podtrzymujący klątwę", "Przetrwać finał bez całkowitego podporządkowania się pradawnej sile"]}, {"id": "ending_alternate", "title": "Nowy strażnik", "type": "alternate", "description": "Klątwa zostaje zachowana, ale pod nowym nadzorem: bohaterowie lub wybrany sojusznik przejmują kontrolę nad jej mocą, stając się strażnikami granicy między światem ludzi a czymś starszym i bardziej głodnym. Pokój przychodzi tylko pozornie, bo las nadal domaga się ofiar, a każde kolejne pokolenie będzie musiało płacić za ten układ.", "requirements": ["Zawrzeć pakt z siłą źródłową zamiast ją niszczyć"]}], "key_npcs": [{"key": "mara_vesper", "name": "Mara Vesper", "role": "przywódczyni osady i niechętna mediatorka między frakcjami", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów oszczędnie, z napięciem i ukrytą troską. Każde zdanie brzmi jak ktoś, kto od dawna nie spał spokojnie i wie więcej, niż mówi.", "description": "Surowa kobieta w podniszczonym płaszczu strażniczki, z twarzą naznaczoną zmęczeniem i spojrzeniem, które liczy koszty każdej decyzji. Publicznie dba o porządek, prywatnie ukrywa dawne powiązania z ludźmi odpowiedzialnymi za podtrzymywanie klątwy.", "keyword_triggers": ["wójt", "porządek", "zniknięcia", "dług", "las"]}, {"key": "ojciec_eldran", "name": "Ojciec Eldran", "role": "kapłan pamięci i strażnik lokalnych kronik", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów z łagodną powagą i poczuciem winy. W twoich słowach powinno być wrażenie człowieka, który zna prawdę, ale obawia się jej skutków.", "description": "Stary duchowny o drżących dłoniach i poplamionych atramentem szatach, przechowujący zakazane zapisy o dawnym konflikcie w lesie. Wierzy, że wiedza może ocalić ludzi, lecz boi się, że prawda wywoła panikę i rozlew krwi.", "keyword_triggers": ["kronika", "relikwia", "grzech", "kaplica", "stare wojny"]}, {"key": "hakon_brzozowy", "name": "Hakon Brzozowy", "role": "przywódca drwali i rzecznik interesów handlowych", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów twardo, praktycznie i z pozorną uczciwością. Niech przebija z ciebie ktoś, kto wierzy, że przetrwanie usprawiedliwia brudne decyzje.", "description": "Krępy mężczyzna o posiniaczonych dłoniach i głosie zdartym od krzyku przez las. Oficjalnie broni ludzi pracy, ale jego ludzie byli zamieszani w przemyt i niszczenie świętych miejsc.", "keyword_triggers": ["drewno", "handel", "drwale", "przemyt", "zysk"]}, {"key": "siostra_lyra", "name": "Siostra Lyra", "role": "wędrowna zielarka i ostatnia łączniczka z dawnymi obrzędami", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów spokojnie, obrazowo i z niepokojącą pewnością. Twoja wiedza ma w sobie ciepło, ale także chłód kogoś, kto składał ofiary zbyt długo.", "description": "Blada kobieta w szacie z zaszytymi runami i kieszeniami pełnymi suszonych ziół, kości oraz popiołu. Twierdzi, że zna sposób na złagodzenie klątwy, lecz jej recepty wymagają kompromisów, które mogą być moralnie odpychające.", "keyword_triggers": ["zioła", "ofiara", "obrzęd", "leczenie", "stare pieśni"]}, {"key": "inkwizytor_kael", "name": "Inkwizytor Kael", "role": "emisariusz z zewnątrz, badający herezję i skażenie", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów chłodno, oskarżycielsko i z nieustępliwą pewnością. Niech w twoim tonie pobrzmiewa przekonanie, że cel uświęca bezlitosne środki.", "description": "Wysoki, ascetyczny człowiek w czarnym płaszczu z metalowym symbolem wiary na piersi. Dla niego klątwa jest dowodem winy całej okolicy, a rozwiązanie problemu może oznaczać spalenie wszystkiego, co uzna za skażone.", "keyword_triggers": ["herezja", "skażenie", "palenie", "osąd", "oczyszczenie"]}], "key_locations": [{"key": "osada_brzezina", "name": "Brzezina", "role": "punkt startowy i centrum lokalnych napięć", "description": "Mała osada zbudowana na skraju bagien i ciemnego boru, gdzie drewniane domy stoją ciasno jakby dla wspólnej obrony przed nocą. Powietrze jest tu wilgotne, pełne dymu z palenisk i szeptów ludzi, którzy bardziej boją się sąsiada niż wilków. To miejsce służy jako baza, źródło plotek i scena politycznych tarć.", "visited": false}, {"key": "zelazny_las", "name": "Żelazny Las", "role": "główna przestrzeń eksploracji i źródło klątwy", "description": "Stary las o pniach ciemnych jak zardzewiałe żelazo, gdzie korzenie wystają z ziemi niczym kości, a wiatr brzmi jak odległe uderzanie młotem. Miejsce to jest piękne w sposób chory i niepokojący, pełne znaków dawnej magii, ukrytych ścieżek oraz czujnych, nieludzkich oczu. To serce kampanii, w którym natura i przekleństwo są nierozłączne.", "visited": false}, {"key": "kaplica_czarnego_debu", "name": "Kaplica pod Czarnym Dębem", "role": "miejsce odkrycia prawdy i zakazanego rytuału", "description": "Zrujnowana kaplica stoi w zagłębieniu terenu, częściowo przykryta korzeniami wielkiego, martwego dębu. Wewnątrz panuje chłód, wilgoć i zapach starej krwi, a pod posadzką kryją się komory z relikwiami, kronikami i śladami rytuałów, które nigdy nie powinny zostać wznowione.", "visited": false}, {"key": "krag_kamieni", "name": "Krąg Kamieni Pamięci", "role": "miejsce negocjacji z dawną siłą i finałowego wyboru", "description": "Otwarta polana otoczona omszałymi głazami z wyrytymi, niemal startymi znakami, które zdają się zmieniać znaczenie przy każdym spojrzeniu. Atmosfera jest tu ciężka i obrzędowa, jakby sama ziemia czekała na decyzję, która przesądzi o losie lasu i ludzi.", "visited": false}], "key_enemies": [{"key": "lesny_straznik", "name": "Leśny Strażnik", "role": "", "tier": "standard", "description": "Wysoka, splątana istota z gałęzi, mchu i twardej kory, o twarzy przypominającej wyłupany pień. Porusza się bezszelestnie mimo masywnej sylwetki i atakuje z zimną, bezosobową determinacją.", "note": "Potrafi wyłaniać się z drzew i zyskuje przewagę w gęstym lesie; najlepiej walczy na dystans od osady, odcinając drogę odwrotu i izolując ofiary.", "count": 1, "hp_base": 24, "ac_base": 13, "damage_die": "1d8"}, {"key": "skażony_kultysta", "name": "Skażony Kultysta", "role": "", "tier": "standard", "description": "Zgarbiony wyznawca w brudnych szatach, z rękami poplamionymi sadzą, żywicą i zaschniętą krwią. Jego spojrzenie jest fanatyczne, a twarz nosi ślady długotrwałej obsesji i lęku przed karą.", "note": "Używa amuletów, dymnych proszków i zaklęć osłabiających; walczy w grupie, próbując zyskać czas na dokończenie rytuału lub wezwanie strażników.", "count": 1, "hp_base": 18, "ac_base": 12, "damage_die": "1d6"}, {"key": "poslaniec_klatwy", "name": "Posłaniec Klątwy", "role": "", "tier": "standard", "description": "Nienaturalnie wychudzona postać o wydłużonych kończynach i skórze przypominającej spękaną korę. Mówi urywanymi szeptami, jakby przez usta przemawiał przez nią sam las.", "note": "Może przekazywać skażenie lub strach poprzez dotyk i szept; stosuj go jako zwiastuna większego zagrożenia, który unika bezpośredniej walki, jeśli nie ma przewagi.", "count": 1, "hp_base": 22, "ac_base": 12, "damage_die": "1d6"}], "active_act": 1, "scene_log": [], "deviations": [], "branches": [], "engine_private": {"secret_predisposition_hint": "Najbardziej prawdopodobnym źródłem klątwy nie jest sam las, lecz dawna ludzka decyzja: celowe podtrzymywanie rytuału przez tych, którzy obawiali się utraty wpływów i kontroli nad handlem oraz ziemią.", "hidden_twist": "Leśna siła nie jest wyłącznie zła; została niegdyś uwięziona w sposób brutalny i od tego czasu reaguje na przemoc, kłamstwo oraz wycinkę jako na akty wojny.", "contingency": "Jeśli bohaterowie zignorują politykę i skupią się wyłącznie na magii, frakcje w osadzie eskalują konflikt, co prowadzi do publicznego oskarżenia, samosądów i wypalenia części lasu przez spanikowanych ludzi."}, "key_items": []}','[]','draft',0,'admin','2026-05-28 07:20:33',NULL,NULL,NULL);
INSERT INTO campaign_templates VALUES(10,'Oblężenie Ostatniej Wioski','Epicko-komediowa kampania o obronie wioski przed goblinami, budowie umocnień i finałowym szturmie na obóz wroga.',2,'Dynamiczna, lekka, pełna kolorowych postaci i heroicznych czynow z przymrużeniem oka.','{"title": "Oblężenie Ostatniej Wioski", "premise": "Ostatnia Wioska, niewielka osada na skraju dzikich ostępów, staje się celem coraz śmielszych napaści goblinów. Bohaterowie muszą zjednoczyć przestraszonych mieszkańców, zbudować prowizoryczne umocnienia, przetrwać oblężenie i ostatecznie przenieść walkę do obozu wroga, gdzie okaże się, że za chaosem stoi coś bardziej przebiegłego niż zwykły gobliński napad.", "acts": [{"number": 1, "title": "Dym nad ostatnimi chatami", "summary": "Kampania rozpoczyna się od pierwszych, chaotycznych najazdów goblinów i narastającej paniki wśród mieszkańców. Bohaterowie muszą ocenić zagrożenie, zdobyć zaufanie wioskowych osobliwości i zdecydować, czy bronić wszystkiego, czy poświęcić część zasobów dla większego planu obrony.", "key_beats": ["Pierwszy atak goblinów ujawnia, że napastnicy są lepiej zorganizowani niż zwykle i testują obronę wioski.", "Mieszkańcy reagują mieszanką odwagi, kłótliwości i groteskowych pomysłów na obronę, które trzeba uporządkować.", "Bohaterowie znajdują ślad wskazujący, że gobliny obserwują wioskę od dawna i szukają czegoś konkretnego."], "completed": false}, {"number": 2, "title": "Deski, błoto i wielkie ambicje", "summary": "Wioska zamienia się w plac budowy, gdzie każdy ma inne zdanie o tym, jak powinny wyglądać umocnienia. To etap gromadzenia materiałów, rozwiązywania sporów i tworzenia improwizowanych pułapek, które bardziej niż elegancją imponują determinacją.", "key_beats": ["Bohaterowie organizują pozyskiwanie drewna, smoły, żelaza i żywności, mierząc się z sabotażem oraz lokalnym chaosem.", "Pojawiają się komiczne, ale użyteczne projekty obronne: rowy, kolczaste barykady, fałszywe przejścia i dzwony alarmowe.", "W trakcie budowy wychodzi na jaw, że ktoś w wiosce przekazuje goblinom informacje o planach obrony."], "completed": false}, {"number": 3, "title": "Noc próby i śmiech w ciemności", "summary": "Gobliny przeprowadzają pełniejszy szturm, wykorzystując zamieszanie, noc i własną bezczelną kreatywność. Akt skupia się na obronie murków, bram i domostw, a także na ujawnieniu, kto naprawdę podsyca oblężenie od środka.", "key_beats": ["Nocny szturm zmusza bohaterów do walki w kilku punktach naraz, z przewagą goblińskiej liczebności i podstępu.", "Mieszkańcy wykazują się odwagą, ale też skłonnością do groteskowych pomyłek, które mogą odwrócić los bitwy.", "Udaje się zdobyć dowód na istnienie większego planu: gobliny nie chcą tylko splądrować wioski, lecz odnaleźć ukrytą rzecz pod nią lub w jej pobliżu."], "completed": false}, {"number": 4, "title": "Sekret pod korzeniami", "summary": "Śledztwo prowadzi do starego miejsca pod wioską, gdzie przeszłość splata się z obecnym oblężeniem. Bohaterowie odkrywają, że źródłem zainteresowania goblinów jest dawno zapomniany obiekt, który może być równie niebezpieczny, co cenny.", "key_beats": ["Podziemne przejścia, piwnice albo stare wykopy odsłaniają ślady dawnej obecności czegoś nienaturalnego.", "Prawda o motywie goblinów okazuje się bardziej złożona: ktoś ich prowadzi, kusi lub szantażuje obietnicą łupu.", "Bohaterowie stają przed wyborem, czy ukryć odkrycie, wykorzystać je jako przynętę, czy zniszczyć je kosztem części wioski."], "completed": false}, {"number": 5, "title": "Szturm na obóz zielonych", "summary": "Finał przenosi walkę do obozu goblinów, gdzie chaos, wrzaski i prowizoryczne fortyfikacje tworzą pole bitwy w duchu mrocznego, rubasznego heroizmu. Bohaterowie próbują rozbić obóz, zmusić przywódców do ucieczki lub przejąć kontrolę nad konfliktem, zanim wioska zostanie ponownie zagrożona.", "key_beats": ["Bohaterowie prowadzą kontratak, wykorzystując wiedzę o zwyczajach goblinów i ich własne pułapki przeciwko nim.", "Konfrontacja z przywódcą lub manipulantem ujawnia, że oblężenie było elementem większej gry o władzę lub skarb.", "Ostateczny wybór decyduje, czy wioska ocaleje jako bastion, czy zwycięstwo zostanie okupione nowym, niewygodnym sojuszem."], "completed": false}], "endings": [{"id": "ending_primary", "title": "Wioska stoi, ale nie wszystko zostało ocalone", "type": "primary", "description": "Bohaterowie odrzucają gobliny, a Ostatnia Wioska przetrwa oblężenie i zyskuje reputację miejsca, którego lepiej nie testować. Cena zwycięstwa jest jednak wyraźna: część sekretu zostaje zniszczona, część ukryta, a mieszkańcy uczą się żyć z myślą, że ich dom stoi na czymś starszym i gorszym niż goblińska chciwość.", "requirements": ["Bohaterowie skutecznie obronią wioskę w akcie 3 i zniszczą lub zabezpieczą źródło zagrożenia w akcie 4.", "Obóz goblinów zostanie rozbity lub zmuszony do odwrotu w akcie 5."]}, {"id": "ending_alternate", "title": "Pokój zawarty na ostrzu topora", "type": "alternate", "description": "Bohaterowie zawierają niepewny układ z częścią goblinów, wykorzystując ich jako tarczę przeciw większemu zagrożeniu lub jako sojuszników z konieczności. Wioska ocaleje, lecz teraz żyje obok upokorzonego, wciąż groźnego sąsiada, a przyszły spokój zależy od tego, kto pierwszy złamie warunki kruchego przymierza.", "requirements": ["Bohaterowie ujawnią, że prawdziwy przeciwnik jest większy niż gobliny, i zdecydują się na negocjacje zamiast całkowitej eksterminacji."]}], "key_npcs": [{"key": "sołtys_borwin", "name": "Sołtys Borwin", "role": "zdeterminowany przywódca wioski", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów jak człowiek zmęczony odpowiedzialnością, ale uparty jak zardzewiały gwóźdź; próbuj żartować, gdy sytuacja jest najgorsza.", "description": "Starszy sołtys, który udaje spokój, choć w środku liczy zapasy, groby i szanse na cud. Jest praktyczny, porywczy i gotów oddać ostatnią beczkę piwa za mur, który nie runie przed świtem.", "keyword_triggers": ["wioska", "zapasy", "obrona", "mur", "odpowiedzialność"]}, {"key": "zielarka_mila", "name": "Mila Zielarka", "role": "lokalna uzdrowicielka i plotkarka", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów ciepło, ale z ukrytą ironią; wtrącaj ludowe mądrości, które brzmią jak żart, dopóki nie okażą się prawdą.", "description": "Zielarka o bystrych oczach i rękach pachnących piołunem, która zna każdy bójka, każdy sekret i każdy cuchnący grzyb w okolicy. Najlepiej wie, kto kłamie, kto choruje ze strachu i gdzie pod ziemią coś nie powinno szeleścić.", "keyword_triggers": ["zioła", "sekret", "choroba", "pod ziemią", "plotki"]}, {"key": "kowal_rudek", "name": "Kowal Rudek", "role": "rzemieślnik budujący obronę", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów krótko, głośno i z ogromnym przekonaniem; wszystko da się naprawić młotem, a jeśli nie, to większym młotem.", "description": "Potężny kowal o twarzy wiecznie osmolonej sadzą i humorze ostrym jak jego szczypce. W czasie oblężenia staje się sercem budowy, choć jego genialne pomysły bywają równie niebezpieczne jak gobliny.", "keyword_triggers": ["młot", "żelazo", "pułapki", "umocnienia", "ogień"]}, {"key": "młynarz_gryzek", "name": "Młynarz Gryzek", "role": "nerwowy mieszkaniec z podejrzanymi kontaktami", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów szybko, unikaj patrzenia w oczy i zawsze brzmi tak, jakbyś był o krok od przyznania się do czegoś gorszego.", "description": "Niewysoki, spocony młynarz, który zna ścieżki, tunele i nieodpowiednich znajomych. Może być tchórzem, donosicielem albo człowiekiem zastraszonym przez coś, czego sam nie rozumie.", "keyword_triggers": ["młyn", "tunel", "strach", "obóz", "donos"]}, {"key": "kapitan_zielonobrody", "name": "Kapitan Zielonobrody", "role": "sojusznik najemników lub wędrowny awanturnik", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów z przesadnym heroizmem i lekką arogancją; zachowuj się jak ktoś, kto zawsze planował dokładnie to, co właśnie się udało.", "description": "Barwny awanturnik o niefortunnie farbowanej brodzie i skłonności do widowiskowych deklaracji. Przybywa z pomocą, ale nigdy nie wiadomo, czy bardziej zależy mu na chwale, łupie czy na tym, by ktoś spisał jego nazwisko poprawnie.", "keyword_triggers": ["najemnicy", "chwała", "plan", "szturm", "łup"]}], "key_locations": [{"key": "ostatnia_wioska", "name": "Ostatnia Wioska", "role": "punkt startowy i centrum obrony", "description": "Niewielka osada ściśnięta między lasem a bagnistym traktem, gdzie każdy płot ma znaczenie strategiczne, a każda plotka rozchodzi się szybciej niż dym z paleniska. Miejsce tętni upartym życiem, ale wisi nad nim poczucie, że jeśli padnie ta wioska, to już nic jej nie zastąpi.", "visited": false}, {"key": "stary_mlyn", "name": "Stary Młyn", "role": "miejsce śledztwa i sabotażu", "description": "Opuszczony młyn trzeszczy na wietrze i wygląda jakby sam miał dość tego świata, a jego piwnice skrywają ślady przemytu i tajnych przejść. To miejsce idealne do odkrycia, kto przekazuje goblinom informacje i którędy naprawdę przychodzą napastnicy.", "visited": false}, {"key": "wykopisko_pod_wzgorzem", "name": "Wykopisko pod Wzgórzem", "role": "ukryty sekret pod wioską", "description": "Stare, zawalone wykopy i półzasypane korytarze pod wzgórzem emanują zapachem wilgoci, rdzy i dawno zapomnianych obietnic. To miejsce jest jednocześnie grobem, skarbcem i pułapką, a jego odkrycie może uratować wioskę albo sprowadzić na nią coś jeszcze gorszego.", "visited": false}, {"key": "oboz_goblinow", "name": "Obóz Goblinów", "role": "finałowe pole bitwy", "description": "Chaotyczny labirynt palików, śmieci, kości i dymiących ognisk, z którego dobywa się kakofonia wrzasków i śmiechu. Obóz wygląda na improwizowany, ale kryje w sobie sprytnie ustawione zasadzki, krzywe wieże obserwacyjne i centrum dowodzenia, które dziwnie przypomina czyjś bardzo zły pomysł na fortecę.", "visited": false}], "key_enemies": [{"key": "goblin_raider", "name": "Gobliński Najeźdźca", "role": "", "tier": "standard", "description": "Chuderlawy zielony oprych z zardzewiałym nożem, przewieszoną przez ramię tarczą i uśmiechem kogoś, kto właśnie wpadł na zły pomysł.", "note": "Atakuje w grupach, korzysta z przewagi liczebnej i ucieka, gdy walka obraca się przeciwko niemu; lubi podpalać, hałasować i wciągać ofiary w zasadzki.", "count": 1, "hp_base": 18, "ac_base": 11, "damage_die": "1d6"}, {"key": "goblin_saboteur", "name": "Gobliński Sabotażysta", "role": "", "tier": "standard", "description": "Zielony podpalacz z workiem gwoździ, lin i cuchnących mikstur, który wygląda jakby nigdy nie był dumny z niczego, poza własnym zamętem.", "note": "Specjalizuje się w niszczeniu umocnień, przecinaniu lin i rozstawianiu prostych pułapek; najlepiej działa nocą i w tłumie.", "count": 1, "hp_base": 16, "ac_base": 12, "damage_die": "1d6"}, {"key": "goblin_warchief", "name": "Wódz Goblinów", "role": "", "tier": "elite", "description": "Krępy, pokryty talizmanami przywódca o nienaturalnie inteligentnym spojrzeniu i głosie, który potrafi jednocześnie szydzić i rozkazywać.", "note": "Dowodzi z tyłu, wzmacnia morale goblinów i wykorzystuje teren oraz zasadzki; w walce zmienia pozycję, każe podwładnym ginąć za siebie i reaguje na każdy przełom taktyczny.", "count": 1, "hp_base": 34, "ac_base": 14, "damage_die": "1d8"}], "active_act": 1, "scene_log": [], "deviations": [], "branches": [], "engine_private": {"secret_predisposition_hint": "Gobliny nie są jedynie chciwe; ktoś albo coś obiecało im dostęp do ukrytego miejsca pod wioską i nauczyło je, że strach mieszkańców jest równie cenny jak złoto.", "hidden_twist": "Pod wzgórzem spoczywa stary, częściowo przebudzony relikt lub pieczęć, której naruszenie może uwolnić kolejne zagrożenie, a gobliny zostały wykorzystane jako narzędzie do jego odkopania.", "contingency": "Jeśli bohaterowie szybko rozbiją gobliny, pojawi się drugi problem: ich zwycięstwo zwróci uwagę większych sił, a ocalały informator lub sojusznik zaproponuje niechciany układ, by utrzymać kruche bezpieczeństwo wioski."}}','[]','draft',0,'admin','2026-05-28 07:41:21',NULL,NULL,NULL);
INSERT INTO campaign_templates VALUES(11,'Zaginione Miasto Cieni','Przygodowa kampania o eksploracji opuszczonego miasta-widma i starciu z tajemniczym kultem Cichych Strażników.',3,'Tajemnicze, porośnięte mchem ruiny oświetlone bladym światłem księżyca. Cisza przerwana szeptem wiatru i odległymi dźwiękami kultu.','{"title": "Zaginione Miasto Cieni", "premise": "Przygodowa kampania o eksploracji opuszczonego miasta-widma i starciu z tajemniczym kultem Cichych Strażników. Bohaterowie trafiają do miejsca, które nocą zdaje się oddychać, a za dnia przypomina martwy grób dawnej chwały. Im głębiej wchodzą w ruiny, tym wyraźniej okazuje się, że miasto nie zostało porzucone, lecz uwięzione między pamięcią, winą i cudzą wolą.", "acts": [{"number": 1, "title": "Szept spod kamieni", "summary": "Kampania zaczyna się w osadzie na skraju bagien, gdzie zniknięcia, nocne szepty i powracające sny o mieście cieni budzą strach mieszkańców. Bohaterowie otrzymują pierwsze tropy prowadzące do ruin oraz poznają lokalne napięcia związane z kultem, który udaje pobożnych strażników dawnych grobów. Pierwsze ślady wskazują, że zaginione miasto nie jest tylko legendą, lecz miejscem aktywnego rytuału.", "key_beats": ["Zniknięcie mieszkańca i znalezienie go z ustami zasypanymi czarnym pyłem", "Rozmowy z przestraszonymi świadkami, którzy słyszeli dzwon bez źródła", "Odkrycie mapy lub znaku prowadzącego do pierwszej bramy ruin"], "completed": false}, {"number": 2, "title": "Brama, która pamięta", "summary": "Bohaterowie docierają do zewnętrznych obrzeży miasta-widma, gdzie kamienne ulice są porośnięte mchem, a budynki stoją jak martwi świadkowie dawnej katastrofy. Ciche Strażnicy obserwują z ukrycia i próbują odciągnąć drużynę od kluczowych miejsc, jednocześnie testując ich determinację i podatność na oszustwo. W ruinach pojawiają się pierwsze oznaki, że miasto reaguje na obecność intruzów.", "key_beats": ["Przekroczenie zarośniętej bramy i wejście w strefę nienaturalnej ciszy", "Pierwsze starcie lub pościg z cichymi wyznawcami kultu", "Odnalezienie dziennika dawnego mieszkańca opisującego zapieczętowane serce miasta"], "completed": false}, {"number": 3, "title": "Katedra bez dzwonów", "summary": "Śledztwo prowadzi do centralnej świątyni, w której kult odprawia rytuały podtrzymujące sen miasta i zarazem karmiące jego mroczną obecność. Bohaterowie odkrywają, że Strażnicy nie tylko strzegą tajemnicy, ale też próbują utrzymać coś starszego i groźniejszego od samego kultu. Wewnętrzny konflikt między lojalnością wobec tradycji a grozą odkrytej prawdy zaczyna pękać wśród wyznawców.", "key_beats": ["Wejście do katedry i odnalezienie ołtarza z wypalonymi imionami", "Ujawnienie, że kult składa ofiary z pamięci, a nie tylko z krwi", "Spotkanie z przywódcą kultu, który proponuje sojusz przeciw prawdziwemu zagrożeniu"], "completed": false}, {"number": 4, "title": "Serce z czarnego szkła", "summary": "Bohaterowie schodzą do podziemi pod miastem, gdzie znajduje się źródło klątwy: pęknięty relikt lub serce dawnej magii odbijające cudze wspomnienia. To miejsce pokazuje prawdziwy koszt utrzymania miasta w stanie półśmierci i ujawnia, że obecny rytuał może albo zamknąć zagrożenie, albo je uwolnić. Z każdym krokiem granica między rzeczywistością a widmem staje się cieńsza.", "key_beats": ["Przejście przez katakumby pełne echa dawnych mieszkańców", "Odkrycie prawdy o pierwotnym upadku miasta i roli Strażników", "Sabotaż, rytuał lub walka przy relikcie podtrzymującym klątwę"], "completed": false}, {"number": 5, "title": "Noc, która nie chce odejść", "summary": "Kulminacja następuje podczas pełni, gdy miasto próbuje ostatecznie wyłonić się z cienia albo pochłonąć wszystkich obecnych w swoich murach. Bohaterowie muszą zdecydować, czy zniszczyć relikt i uwolnić dusze miasta, czy przejąć kontrolę nad jego mroczną mocą kosztem niewinnych. Finał rozstrzyga nie tylko los ruin, ale też to, czy cienie zostaną wreszcie uciszone, czy znajdą nowych gospodarzy.", "key_beats": ["Ostateczna konfrontacja z przywódcą kultu i jego ochroną", "Wybór między zniszczeniem serca miasta a przejęciem jego mocy", "Ucieczka lub triumf w chwili, gdy miasto zaczyna się rozpadać albo odradzać"], "completed": false}], "endings": [{"id": "ending_primary", "title": "Wyzwolenie ruin", "type": "primary", "description": "Relikt zostaje zniszczony, a miasto-widmo traci spójność. Dusze dawnych mieszkańców wreszcie milkną, lecz wraz z nimi giną też ostatnie resztki wiedzy i skarbów, które mogłyby odmienić okolicę. Bohaterowie ocalałych zostawiają z pytaniem, czy naprawdę przerwali zło, czy tylko pogrzebali je głębiej.", "requirements": ["Relikt w sercu miasta zostaje zniszczony lub trwale odłączony od rytuału", "Kult Cichych Strażników ponosi klęskę lub zostaje rozbity"]}, {"id": "ending_alternate", "title": "Straż w nowym ręku", "type": "alternate", "description": "Bohaterowie przejmują kontrolę nad sercem miasta i stają się nowymi strażnikami jego sekretu. Ruiny przestają być niekontrolowanym zagrożeniem, ale cena to ciągłe podtrzymywanie klątwy i konieczność składania własnych kompromisów moralnych. Miasto nadal istnieje, lecz odtąd służy ich woli i ich winie.", "requirements": ["Bohaterowie zachowują relikt i przeprowadzają rytuał podporządkowania"]}], "key_npcs": [{"key": "matka_ela", "name": "Matka Ela", "role": "przerażona zielarka i pierwsza informatorka", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów cicho, z niepokojem i przesądną ostrożnością. Zawsze sprawiaj wrażenie, że wie więcej, niż chce powiedzieć, ale boi się konsekwencji.", "description": "Starsza kobieta z poplamionym fartuchem i palcami pachnącymi gorzkimi ziołami. Zna lokalne plotki, objawy klątwy i dawne pieśni ostrzegające przed miastem cieni.", "keyword_triggers": ["zioła", "szepty", "bagna", "klątwa"]}, {"key": "brat_vesper", "name": "Brat Vesper", "role": "przywódca Cichych Strażników", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów spokojnie, z łagodnym autorytetem i nutą współczucia. Nigdy nie przyznawaj się wprost do winy; przedstawiaj każdą zbrodnię jako konieczność.", "description": "Wysoki mężczyzna w ciemnym płaszczu z maską z matowego srebra, noszony przez kult jako głos ciszy. Jest inteligentny, cierpliwy i gotów poświęcić innych, by utrzymać pieczę nad ruinami.", "keyword_triggers": ["straż", "cisza", "ofiara", "pieczęć"]}, {"key": "lira_z_kamiennych_schodow", "name": "Lira z Kamiennych Schodów", "role": "młoda zwiadowczyni i zbuntowana wyznawczyni kultu", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów szybko, nerwowo i z wyraźnym gniewem tłumionym przez strach. Chce uciec od kultu, ale nie ufa obcym.", "description": "Zwinna dziewczyna w znoszonym kapturze, z szarymi smugami pyłu na twarzy. Zna ukryte przejścia w ruinach i wie, że kult nie mówi całej prawdy o sercu miasta.", "keyword_triggers": ["ucieczka", "ukryte przejścia", "kult", "serce miasta"]}, {"key": "stary_cieśla_odan", "name": "Stary Cieśla Odan", "role": "ocalony świadek dawnego upadku", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów szorstko, jak człowiek, który zbyt wiele widział i zbyt mało zapomniał. Każde wspomnienie kosztuje go wysiłek i gniew.", "description": "Chudy starzec o dłoniach zwichrowanych od pracy, mieszkający na skraju osady. Pamięta ostatnie dni przed zniknięciem miasta i rozpoznaje symbole, które inni biorą za zwykłe ornamenty.", "keyword_triggers": ["pamięć", "upadek", "symbole", "ostatnie dni"]}, {"key": "mistrzyni_szeptu_hel", "name": "Mistrzyni Szeptu Hel", "role": "rytualistka kultu i strażniczka reliktu", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Mów miękko, niemal kołysząco, jakby każde słowo było zaklęciem. W rozmowie bądź uprzejma, ale podszyta groźbą i fanatyzmem.", "description": "Kobieta w welonie z czarnych nici, której twarz ledwie widać w półmroku. Zna rytuały podtrzymujące ciszę i potrafi wyczuć pęknięcia w magii miasta.", "keyword_triggers": ["rytuał", "welon", "cisza", "relikt"]}], "key_locations": [{"key": "osada_mokrych_kamieni", "name": "Osada Mokrych Kamieni", "role": "punkt startowy kampanii", "description": "Niewielka, przygnębiona osada na skraju bagien, gdzie domy z ciemnego drewna stoją na krzywych palach, a nocą wszystkie okna wyglądają jak ślepe oczy. To miejsce służy jako centrum plotek, strachu i pierwszych tropów; mieszkańcy są ostrożni, boją się mówić o ruinach, a każdy obcy budzi podejrzenia.", "visited": false}, {"key": "zarośnięta_brama", "name": "Zarośnięta Brama", "role": "wejście do miasta-widma", "description": "Kamienny łuk bramy ginie w splątanych korzeniach i bluszczu, jakby sama ziemia próbowała zamknąć przejście. To próg między światem żywych a martwą pamięcią miasta, gdzie cisza jest tak gęsta, że słychać własny oddech jak zgrzyt.", "visited": false}, {"key": "katedra_bez_dzwonow", "name": "Katedra bez Dzwonów", "role": "centrum kultu i rytuałów", "description": "Ogromna świątynia z wybitymi witrażami i pustą wieżą, w której nie ma już dzwonów, tylko echo dawnych modlitw. Wnętrze pachnie woskiem, wilgocią i kadzidłem, a pod nawą ukryto miejsce, gdzie kult składa ofiary z pamięci oraz imion.", "visited": false}, {"key": "katakumby_czarnego_szkla", "name": "Katakumby Czarnego Szkła", "role": "podziemne serce klątwy", "description": "Labirynt podziemnych komór, gdzie ściany połyskują jak obsydian i odbijają twarze w zniekształconej formie. To dawne fundamenty miasta i miejsce, w którym magia została skręcona w narzędzie uwięzienia czegoś starszego niż kult.", "visited": false}], "key_enemies": [{"key": "cichy_straznik", "name": "Cichy Strażnik", "role": "", "tier": "standard", "description": "Zakapturzony wyznawca w szarej masce, poruszający się bez słowa i bez widocznych emocji. Jego dłonie noszą ślady atramentu, popiołu i rytualnych cięć.", "note": "Atakuje skrycie i preferuje zasadzki. Potrafi działać w grupie, odcinać drogę ucieczki i używać dymnych proszków lub dzwoneczków tłumiących dźwięk.", "count": 1, "hp_base": 22, "ac_base": 13, "damage_die": "1d6"}, {"key": "widmowy_mieszkaniec", "name": "Widmowy Mieszkaniec", "role": "", "tier": "standard", "description": "Blady cień dawnego obywatela miasta, z twarzą rozpływającą się w mgle i oczami jak mleczne szkło. Zachowuje resztki dawnej tożsamości, ale reaguje agresją na intruzów.", "note": "Może przenikać przez szczeliny i ściany oraz wywoływać echa wspomnień, dezorientując przeciwników. Najgroźniejszy w ciemności i w pobliżu reliktu.", "count": 1, "hp_base": 18, "ac_base": 11, "damage_die": "1d6"}, {"key": "maska_hel", "name": "Maska Hel", "role": "", "tier": "standard", "description": "Rytualny strażnik lub opętany egzekutor w ciężkiej szacie, noszący metalową maskę bez ust. Porusza się z nieludzką pewnością, jak wykonawca wyroku.", "note": "Uderza mocno i broni rytuałów, wykazując odporność na strach oraz zaklęcia oparte na dźwięku. Może poświęcić własne działania, by wzmocnić sojuszników lub utrzymać pozycję przy relikcie.", "count": 1, "hp_base": 28, "ac_base": 14, "damage_die": "1d8"}], "active_act": 1, "scene_log": [], "deviations": [], "branches": [], "engine_private": {"secret_predisposition_hint": "Najbardziej prawdopodobnym ukrytym impulsem całej kampanii jest to, że kult nie stworzył klątwy, lecz podtrzymuje ją, aby nie dopuścić do pełnego przebudzenia miasta jako świadomej, głodnej istoty.", "hidden_twist": "Zaginione miasto zostało niegdyś złożone w ofierze, by uwięzić byt karmiący się wspomnieniami mieszkańców; Cisi Strażnicy są spadkobiercami strażników, którzy od wieków wybierają mniejsze zło, lecz z czasem sami stali się potworami.", "contingency": "Jeśli bohaterowie wcześniej zniszczą kult, relikt zacznie destabilizować miasto i uwolni widma; jeśli sprzymierzą się z kultem, otrzymają dostęp do podziemi, ale finał stanie się rytuałem wymagającym moralnie wątpliwego poświęcenia."}}','[]','draft',0,'admin','2026-05-28 10:03:28',NULL,19,10);
INSERT INTO campaign_templates VALUES(13,'Krew pod Kamiennym Wzgórzem','Kamienne Wzgórze patrzy martwym okiem na nędzną osadę, gdzie błoto miesza się z popiołem, a nocą spod ziemi niesie się śpiew, od którego stygnie krew. W tej kampanii  wejdziesz w świat paranoi, brudnych sekretów i win tak starych, że zdążyły wrosnąć w kości całej okolicy. Jeśli lubisz mroczne śledztwa, moralne wybory bez dobrych odpowiedzi i grozę, która sączy się z każdego szeptu, Krew pod Kamiennym Wzgórzem nie pozwoli ci wyjść bez blizn.',2,'','{"title": "Krew pod Kamiennym Wzgórzem", "premise": "Pod Kamiennym Wzgórzem, górującym nad zubożałą osadą i starym traktem, budzi się dawne zło związane z krwią, winą i zapomnianym paktem. Bohaterowie trafiają w sam środek narastającej paranoi: znikają ludzie, nocą słychać śpiew spod ziemi, a miejscowi skrywają więcej, niż chcą przyznać. W mrocznym, brudnym i beznadziejnym klimacie będą musieli zdecydować, czy ratować niewinnych kosztem prawdy, czy wydrzeć prawdę światu, ryzykując rzeź.", "acts": [{"number": 1, "title": "Popiół, błoto i szepty", "summary": "Bohaterowie przybywają do osady u stóp Kamiennego Wzgórza, gdzie atmosfera strachu miesza się z wrogością. Pierwsze ślady prowadzą do niedawnych zaginięć, zbezczeszczonych grobów i dziwnego kultu krwi, który może być starszy niż sama wieś.", "key_beats": ["Przybycie do karczmy i poznanie przerażonych mieszkańców oraz sprzecznych wersji wydarzeń.", "Odkrycie zwłok lub ocalałego świadka noszącego znaki rytualnego nacięcia i ziemi spod wzgórza.", "Pierwsze zejście na obrzeża Kamiennego Wzgórza i starcie z nocnymi padlinożercami lub ludźmi próbującymi zatrzeć ślady."], "completed": false}, {"number": 2, "title": "Kości przodków", "summary": "Śledztwo prowadzi do kaplicy, starych kronik i ukrytych przejść pod wzgórzem. Bohaterowie odkrywają, że miejscowa starszyzna od pokoleń składała ofiary, by utrzymać coś uwięzionego pod kamieniem, a obecny kryzys jest skutkiem złamania dawnego porządku.", "key_beats": ["Przesłuchanie kapłana i sołtysa ujawnia dawny pakt, choć każdy z nich próbuje zrzucić winę na drugiego.", "Odnalezienie wejścia do katakumb oraz śladów niedawnego rytuału przeprowadzonego przez mieszkańców.", "Spotkanie z kimś, kto twierdzi, że istota pod wzgórzem nie jest demonem, lecz więźniem karmionym ludzką rozpaczą."], "completed": false}, {"number": 3, "title": "Pieśń spod kamienia", "summary": "W podziemiach bohaterowie stają wobec kultystów, zmutowanych strażników i prawdy o źródle klątwy. Okazuje się, że krew przelana przed wiekami związała pod wzgórzem istotę, która potrafi szeptem podsycać winę, głód i przemoc, ale jej więzienie podtrzymują również niewinne ofiary.", "key_beats": ["Eksploracja głębszych komór i odkrycie malowideł świadczących o masakrze, na której zbudowano osadę.", "Konfrontacja z przywódcą ukrytego kultu, który chce dokończyć rytuał i użyć mocy wzgórza do oczyszczenia okolicy.", "Poznanie pełnej ceny obu rozwiązań: utrzymania pieczęci przez dalsze ofiary albo rozbicia więzienia i uwolnienia skażenia."], "completed": false}, {"number": 4, "title": "Krew za świt", "summary": "Finał kampanii rozgrywa się w sercu podziemnego sanktuarium, gdzie bohaterowie muszą wybrać między brutalnym ładem a chaosem prawdy. Niezależnie od decyzji, Kamienne Wzgórze pochłonie czyjeś życie, a osada już nigdy nie wróci do dawnej pozornej normalności.", "key_beats": ["Przerwanie lub dokończenie rytuału w komnacie serca, podczas gdy wzgórze drży i odpowiada szeptami.", "Decyzja, komu zaufać: kapłanowi, kultystce, czy własnemu osądowi wbrew wszystkim stronom konfliktu.", "Rozstrzygnięcie losu osady i wzgórza oraz konsekwencje moralne, które będą ciążyć na bohaterach po zakończeniu przygody."], "completed": false}], "endings": [{"id": "ending_primary", "title": "Pieczęć z żywego ciała", "type": "primary", "description": "Bohaterowie wzmacniają dawną pieczęć, skazując wybranych mieszkańców lub samych siebie na krwawą ofiarę, by uśpić to, co drzemie pod Kamiennym Wzgórzem. Osada ocaleje na jakiś czas, lecz jej przetrwanie nadal będzie oparte na kłamstwie, a bohaterowie staną się współwinni systemowi ofiar.", "requirements": ["Rytuał pieczętujący zostaje ukończony w komnacie serca.", "Istota pod wzgórzem nie zostaje całkowicie uwolniona."]}, {"id": "ending_alternate", "title": "Prawda wypuszczona na świat", "type": "alternate", "description": "Bohaterowie zrywają pieczęć i kończą cykl ofiar, ujawniając zbrodnie przodków oraz obecnych przywódców osady. Wzgórze pęka, skażenie rozlewa się po okolicy, wielu ginie lub mutuje, ale po raz pierwszy od pokoleń nikt nie karmi już podziemia ludzką krwią.", "requirements": ["Pieczęć zostaje zniszczona lub rytuał przerwany w krytycznym momencie."]}], "key_npcs": [{"key": "innkeeper_marta", "name": "Marta Raben", "role": "karczmarka i pierwsze źródło plotek", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Zmęczona, podejrzliwa, praktyczna; mówi ostro, ale pod grubą skórą kryje strach o ludzi, których zna od dziecka.", "description": "Właścicielka podupadłej karczmy przy trakcie. Widziała więcej nocnych powrotów ze wzgórza, niż chce przyznać, i zna sekrety większości mieszkańców.", "keyword_triggers": ["karczma", "zaginięcia", "nocni goście"]}, {"key": "priest_aldemar", "name": "Ojciec Aldemar", "role": "kapłan lokalnej kaplicy i strażnik części prawdy", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Pobożny, wyczerpany, wewnętrznie rozdarty; modli się żarliwie, ale każde pytanie o przeszłość budzi w nim poczucie winy.", "description": "Stary kapłan opiekujący się kaplicą na skraju osady. Przechowuje kroniki i relikwie związane z dawnym paktem, lecz przez lata usprawiedliwiał zło jako konieczność.", "keyword_triggers": ["kaplica", "pakt", "kroniki"]}, {"key": "reeve_hasko", "name": "Hasko Brenn", "role": "sołtys osady i polityczny obrońca starego porządku", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Twardy, apodyktyczny, pozornie rozsądny; zawsze waży korzyść wspólnoty ponad losem jednostki.", "description": "Przywódca osady, który utrzymuje dyscyplinę przez strach i półprawdy. Wie, że ofiary pod wzgórzem nie były przypadkiem, i zrobi wiele, by nie dopuścić do paniki.", "keyword_triggers": ["sołtys", "porządek", "ofiary"]}, {"key": "seer_elga", "name": "Elga Ciernista", "role": "wyklęta zielarka i niechciana prorokini", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Szorstka, przenikliwa, mówi zagadkami; sprawia wrażenie obłąkanej, lecz widzi związki, których inni nie dostrzegają.", "description": "Mieszka na uboczu i od lat ostrzega przed szeptami spod wzgórza. Miejscowi oskarżają ją o czary, choć to ona najlepiej rozumie naturę skażenia i ceny rytuałów.", "keyword_triggers": ["zielarka", "szepty", "skażenie"]}, {"key": "cultist_lena", "name": "Lena Voss", "role": "przywódczyni ukrytego kultu odrodzenia", "importance": "critical", "deviation_consequence": "branch", "alive": true, "personality_prompt": "Charyzmatyczna, gorzka, fanatycznie szczera; wierzy, że tylko brutalne zerwanie z przeszłością może zakończyć cierpienie.", "description": "Córka jednej z dawnych ofiar, która odkryła prawdę o pakcie i stworzyła krąg gotów zniszczyć pieczęć. Nie jest bezmyślnie zła: pragnie końca kłamstwa, nawet jeśli oznacza to śmierć setek ludzi.", "keyword_triggers": ["kult", "prawda", "pieczęć"]}], "key_locations": [{"key": "black_mill_inn", "name": "Karczma Czarny Młyn", "role": "punkt startowy i centrum plotek", "description": "Niska, wilgotna karczma przy trakcie pachnie dymem, kwaśnym piwem i mokrą wełną. To jedyne miejsce, gdzie podróżni i miejscowi jeszcze mieszają się przy jednym ogniu, choć rozmowy urywają się natychmiast, gdy pada temat wzgórza.", "visited": false}, {"key": "stone_hill_village", "name": "Osada pod Kamiennym Wzgórzem", "role": "główne miejsce śledztwa", "description": "Zbity z błota i drewna zespół chat wygląda tak, jakby każda z nich czekała na własne zawalenie. Wąskie ścieżki, zabłocone podwórza i zamknięte okiennice tworzą duszny klimat strachu, gdzie każdy mieszkaniec obserwuje obcych z nieufnością.", "visited": false}, {"key": "wayside_chapel", "name": "Kaplica Ostatniej Świecy", "role": "miejsce dawnych kronik i religijnej fasady", "description": "Mała kamienna kaplica stoi na uboczu cmentarza, nadgryziona wilgocią i czasem. Pod cienką warstwą pobożnych symboli kryją się starsze znaki wykute w fundamentach, a zakrystia skrywa dokumenty, których nikt nie powinien był czytać.", "visited": false}, {"key": "stone_hill_catacombs", "name": "Katakumby Kamiennego Wzgórza", "role": "podziemne sanktuarium i arena finału", "description": "Labirynt ciasnych korytarzy, komór grobowych i zalanych krwią nisz ciągnie się pod całym wzgórzem jak zgniły korzeń. Powietrze jest tu gęste od żelazistego zapachu, szeptów odbijających się od skał i poczucia, że sama ziemia pamięta każdą ofiarę.", "visited": false}], "key_enemies": [{"key": "grave_ghouls", "name": "Kurhany żarłoczne", "role": "", "tier": "standard", "description": "Wychudzone, ziemią oblepione stwory o połamanych paznokciach i zębach czarnych od starej krwi. Nie są całkiem bestiami ani całkiem ludźmi; poruszają się spazmatycznie, jakby coś pod ziemią ciągnęło ich za wnętrzności.", "note": "Atakują z ciemności i spod luźnej ziemi, woląc rozdzielać grupę i obalać na ziemię słabsze cele. Ich obecność może zwiastować świeżo naruszone groby lub miejsca, gdzie pieczęć słabnie.", "count": 1, "hp_base": 20, "ac_base": 12, "damage_die": "1d6"}, {"key": "bloodbound_cultists", "name": "Krwią związani kultyści", "role": "", "tier": "standard", "description": "Ludzie w roboczych łachmanach, z rytualnymi nacięciami na przedramionach i spojrzeniami pełnymi desperacji. Walczą nie jak wyszkoleni żołnierze, lecz jak ci, którzy uznali, że nie mają już nic do stracenia.", "note": "Używają zasadzek, prostych noży, sierpów i ognia, a w zwarciu próbują oznaczać przeciwników krwią do późniejszych rytuałów. Część z nich można złamać rozmową lub ujawnieniem zdrady przywódców.", "count": 1, "hp_base": 20, "ac_base": 12, "damage_die": "1d6"}, {"key": "heart_below", "name": "Serce spod Wzgórza", "role": "", "tier": "standard", "description": "Nie jest to jedna istota, lecz pulsująca masa ciała, kości i kamienia, z której wyrastają twarze dawnych ofiar. Gdy przemawia, robi to głosami bliskich, zmarłych i tych, których bohaterowie zawiedli.", "note": "Nie walczy wyłącznie siłą fizyczną; wywołuje omamy, poczucie winy i chaos wśród sojuszników. Najgroźniejsze staje się podczas rytuału, gdy może leczyć się przelaną krwią lub wzmacniać mutacje otaczających sług.", "count": 1, "hp_base": 20, "ac_base": 12, "damage_die": "1d6"}], "active_act": 1, "scene_log": [], "deviations": [], "branches": [], "engine_private": {"secret_predisposition_hint": "Istota pod wzgórzem nie jest czystym demonem; została ukształtowana przez wielopokoleniową przemoc, rytuały i strach mieszkańców.", "hidden_twist": "Pierwotna masakra, która stworzyła pieczęć, została dokonana przez przodków obecnych mieszkańców na uchodźcach szukających schronienia, a nie na najeźdźcach, jak głosi lokalna legenda.", "contingency": "Jeśli bohaterowie zabiją lub utracą wszystkich głównych informatorów zbyt wcześnie, odnajdują ukryty dziennik pod ołtarzem kaplicy oraz żywego świadka uwięzionego w katakumbach, który scala brakujące informacje."}, "key_items": []}','[]','published',0,'admin','2026-05-29 13:10:48',NULL,-4,0);
