INSERT INTO dungeon_tile_categories VALUES('dungeon','Loch','Klasyczne podziemia, kamienne ściany, pochodnie','dark stone dungeon walls, torch sconces, medieval',10,1,'2026-06-01 09:44:49',replace('Prowadź loch jak klasyczne, bezlitosne podziemia wykute w zimnym kamieniu, gdzie każdy korytarz obiecuje tajemnicę i grozę. Buduj atmosferę ciężaru, wilgoci i odosobnienia; niech światło pochodni drży na ścianach, wydłużając cienie i zniekształcając kształty. Utrzymuj średni do wysokiego poziom mroku i stałe poczucie zagrożenia, jakby za każdym rogiem czaiła się pułapka, potwór albo ślad dawnej tragedii. Sprawiaj, by loch wydawał się stary, zapomniany i nieprzyjazny wobec żywych.\n\nOpisuj komnaty konkretnie i zmysłowo: podkreślaj surowe kamienne ściany, popękane płyty, sklepienia, żelazne kraty, wilgotne narożniki, ślady krwi, kości lub porzucone przedmioty. Akcentuj dźwięki kapania wody, trzask pochodni, echo kroków, chrobot za ścianą, nagłą ciszę i odległe jęki. Wplataj zapach stęchlizny, dymu, pleśni, rdzy i gnijącego mięsa. Buduj nastrój napięcia, klaustrofobii i niepewności; dawaj graczom poczucie, że światło jest kruche, zasoby ograniczone, a każdy wybór może ich przybliżyć do skarbu albo śmierci.','\n',char(10)));
