INSERT INTO dungeon_tiles VALUES(3,'dungeon','Boss Chamber','/images/tiles/dungeon_tile_3_1780337351.png','throne chamber with bones and rubble, cracked stone throne, battle damage','["N"]','throne chamber with bones','[{"enemy_key": "wolf", "count": 1, "overlays": [{"x": 0.4942307692307692, "y": 0.6548076923076924, "scale": 0.40999999999999975, "rot": -179.5}]}]','[{"chance": 0.5, "weapon_key": "flail"}]','[]',NULL,'[]',1,1,'2026-06-01 09:57:41','2026-06-01 18:10:04','/images/tiles/dungeon_tile_3_raw_1780337351.png','{}');
INSERT INTO dungeon_tiles VALUES(4,'cave','Jaskinia zaglady','/images/tiles/dungeon_tile_4_1780325911.png','Gloomhaven dungeon tile art style, top down view, flat 2D illustration, stone floor, thick dark stone walls forming square border, fantasy board game tile, overhead perspective, square tile format, painted game art, cartoonish style, natural cave chamber, rock walls, stalactites, glowing crystals, Gloomhaven dungeon tile art style, top down view, flat 2D illustration, stone floor, thick dark stone walls forming square border, fantasy board game tile, overhead perspective, square tile format, painted game art, cartoonish style, natural cave chamber, rock walls, stalactites, glowing crystals, gap openings in north wall and south wall and east wall, gap openings in north wall and south wall and east wall','["N", "S", "E"]','','[]','[]','[]',NULL,'[]',0,0,'2026-06-01 12:50:06','2026-06-01 14:58:31',NULL,'{}');
INSERT INTO dungeon_tiles VALUES(5,'dungeon','Główny Korytarz','/images/tiles/dungeon_tile_5_1780346923.png','dark fantasy dungeon stone corridor, torches on walls, wet stone floor, flickering firelight casting long shadows, ancient brick walls, atmospheric fog, game art style, detailed, moody lighting, doors north and south','["N", "S"]','Długi kamienny korytarz rozciąga się przed tobą. Pochodnie w żelaznych uchwytach rzucają drżące cienie na wilgotne mury. Powietrze pachnie stęchlizną i saletrą.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-01 20:48:45','/images/tiles/dungeon_tile_5_raw_1780346843.png','{}');
INSERT INTO dungeon_tiles VALUES(6,'dungeon','Skrzyżowanie Dróg','/images/tiles/dungeon_tile_6_1780378291.png','dark fantasy dungeon crossroads chamber, four passages in cardinal directions, stone pillar in center, carved map relief, ancient dungeon, atmospheric torchlight, stone arch doorways, game art style','["N", "W", "E", "S"]','Cztery korytarze zbiegają się w tej okrągłej komnacie. Pośrodku stoi kamienny słup z wyrytą mapą. Z każdego przejścia dobiega inny dźwięk.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-02 05:31:42','/images/tiles/dungeon_tile_6_raw_1780378291.png','{}');
INSERT INTO dungeon_tiles VALUES(7,'dungeon','Zbrojownia','/images/tiles/dungeon_tile_7_1780378398.png','dark fantasy dungeon armory room, empty weapon racks on stone walls, rusted armor pieces, broken swords, wooden chest, dungeon storage room, moody torchlight, cobwebs, game art style','["N", "E"]','Ściany pokrywają stojaki na broń — większość pusta, rdzą pokryta, ale kilka trzyma szczątki pancerzy i złamane ostrza.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-02 05:36:16','/images/tiles/dungeon_tile_7_raw_1780378398.png','{}');
INSERT INTO dungeon_tiles VALUES(8,'dungeon','Cele Więzienne','/images/tiles/dungeon_tile_8_1780501872.png','dark fantasy dungeon prison cells, iron bar doors, chains on stone walls, old bones on floor, one cell door broken, atmospheric darkness, single torch, despair atmosphere, game art style, doors south and west','["S", "W"]','Szereg małych cel za grubymi kratami żelaznymi. Łańcuchy na ścianach, stare kości na podłodze. Jedna z krat jest wyrwana ze ściany.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-03 15:51:12','/images/tiles/dungeon_tile_8_raw_1780501872.png','{"S": {"x": 0.5, "y": 0.931640625, "scale": 1.0, "rot": 180}, "W": {"x": 0.068359375, "y": 0.5, "scale": 1.0, "rot": 90}}');
INSERT INTO dungeon_tiles VALUES(9,'dungeon','Kaplica Ciemności','/images/tiles/dungeon_tile_9_1780330977.png','dark fantasy dungeon chapel, black stone altar, faded wall murals with masked figures, eternal candle flame, dark deity shrine, ancient dungeon worship room, eerie candlelight, game art style','["N", "S"]','Mała kaplica poświęcona zapomnianemu bóstwu. Ołtarz z czarnego kamienia, wyblakłe malowidła naścienne. Na ołtarzu stoi świeca, która sama z siebie nie gaśnie.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-01 16:23:15','/images/tiles/dungeon_tile_9_raw_1780330977.png','{"N": {"x": 0.5, "y": 0.068359375, "scale": 1.0, "rot": 0}, "S": {"x": 0.5, "y": 0.931640625, "scale": 1.0, "rot": 180}}');
INSERT INTO dungeon_tiles VALUES(10,'dungeon','Biblioteka Czarnoksiężnika','/images/tiles/dungeon_tile_10_1780329664.png','bookshelves full of ancient scrolls and spell books, arcane tomes eaten by time and mold, pale runes flickering between pages doors east and west','["E", "W"]','Półki pełne zwojów i ksiąg, wiele zjedzonych przez czas i pleśń. Między kartami migają blade runy.','[]','[]','[]',NULL,'[]',0,0,'2026-06-01 13:56:14','2026-06-01 16:50:15','/images/tiles/dungeon_tile_10_raw_1780329167.png','{"E": {"x": 0.93, "y": 0.85, "scale": 1.5, "rot": 270}, "W": {"x": 0.07, "y": 0.15, "scale": 1.5, "rot": 90}}');
INSERT INTO dungeon_tiles VALUES(11,'dungeon','Sala Tronowa','/images/tiles/dungeon_tile_11_1780348552.png','dark fantasy dungeon throne room, black stone throne on raised platform, decayed carpet, faded dynasty banners on walls, ruined grandeur, dramatic torchlight from wall sconces, imposing atmosphere, game art style','["W", "E", "S"]','Wielka komnata z tronem z czarnego kamienia na podwyższeniu. Na ścianach wiszą wyblakłe chorągwie rodu, którego już nie ma.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-02 05:30:41','/images/tiles/dungeon_tile_11_raw_1780348552.png','{}');
INSERT INTO dungeon_tiles VALUES(12,'dungeon','Skarbiec','/images/tiles/dungeon_tile_12_1780378265.png','dark fantasy dungeon treasury room, broken treasure chests, scattered gold coins on floor, empty shelves, open vault door, some remaining loot in corner, looted room atmosphere, torchlight, game art style','["N", "S"]','Ciężkie drzwi do skarbca stoją otworem — ktoś był tu przed tobą. Na podłodze rozsypane monety, strzaskane skrzynie.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-02 05:31:09','/images/tiles/dungeon_tile_12_raw_1780378265.png','{}');
INSERT INTO dungeon_tiles VALUES(13,'dungeon','Laboratorium Alchemika','/images/tiles/dungeon_tile_13_1780332184.png','dark fantasy dungeon alchemy laboratory, stone tables with glass flasks bubbling, distillation apparatus, formula charts on walls, dried herbs, mysterious potions, eerie green glow from vials, game art style','["N", "W"]','Stoły zastawione destylatorami i kolbami. Kilka z nich wciąż bulgocze. Na ścianie tablice z formułami, część zakrwawiona.','[]','[]','[]',NULL,'[]',0,0,'2026-06-01 13:56:14','2026-06-01 16:43:04','/images/tiles/dungeon_tile_13_raw_1780332184.png','{"N": {"x": 0.5, "y": 0.068359375, "scale": 1.0, "rot": 0}, "W": {"x": 0.068359375, "y": 0.5, "scale": 1.0, "rot": 90}}');
INSERT INTO dungeon_tiles VALUES(14,'dungeon','Izba Tortur','/images/tiles/dungeon_tile_14_1780348016.png','dark fantasy dungeon torture chamber, iron maiden in corner, interrogation table with leather straps, hooks hanging from ceiling with tongs, dark bloodstained stone floor, grim medieval implements, atmospheric horror, game art style, doors south and east','["E", "S"]','Komnata zgrozy. Stół przesłuchań z rzemiennymi pasami, szafa żelaznej dziewicy w kącie. Podłoga ciemna od zaschniętej krwi.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-01 21:07:03','/images/tiles/dungeon_tile_14_raw_1780348016.png','{}');
INSERT INTO dungeon_tiles VALUES(15,'dungeon','Komnata Strażników','/images/tiles/dungeon_tile_15_1780337431.png','dark fantasy dungeon guard room, dice table, straw mattresses, spear rack on wall, rough dungeon floor plan sketch, guard barracks atmosphere, fireplace embers, game art style, lived-in feel','["N", "S", "W"]','Izba dawnej warty. Stół do gry w kości, kilka sienników, stojak na włócznie. Na ścianie plan lochów.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-01 18:10:31','/images/tiles/dungeon_tile_15_raw_1780337431.png','{"N": {"x": 0.5, "y": 0.068359375, "scale": 1.0, "rot": 0}, "S": {"x": 0.5, "y": 0.931640625, "scale": 1.0, "rot": 180}, "W": {"x": 0.068359375, "y": 0.5, "scale": 1.0, "rot": 90}}');
INSERT INTO dungeon_tiles VALUES(16,'dungeon','Sala Ceremonii','/images/tiles/dungeon_tile_16_1780334276.png','dark ritual chamber, circular magic circle engraved in floor, ring of black candles some still burning, ancient occult symbols on walls','["N", "W", "E"]','Okrągła komnata z magicznym kręgiem w posadzce. Na obwodzie krąg czarnych świec, część nadal się pali. Na środku plama sczerniałej krwi.','[{"enemy_key": "wolf", "count": 1, "overlays": [{"x": 0.5, "y": 0.5, "scale": 0.35, "rot": 0}]}]','[{"chance": 0.5, "item_key": "potion_healing_large"}, {"chance": 0.5, "weapon_key": "longsword"}]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-01 17:17:57','/images/tiles/dungeon_tile_16_raw_1780334276.png','{"N": {"x": 0.5, "y": 0.068359375, "scale": 1.0, "rot": 0}, "W": {"x": 0.068359375, "y": 0.5, "scale": 1.0, "rot": 90}, "E": {"x": 0.931640625, "y": 0.5, "scale": 1.0, "rot": 270}}');
INSERT INTO dungeon_tiles VALUES(17,'dungeon','Sala Map','/images/tiles/dungeon_tile_17_1780348425.png','dark fantasy dungeon map room, large stone table with spread dungeon map, bone game pieces marking positions, battle plans on walls, cartography tools, strategic planning chamber, torchlight, game art style','["E", "S"]','Strategiczna komnata z wielkim stołem, na którym leży mapa lochów. Pionki z kości oznaczają pozycje oddziałów.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-01 21:13:56','/images/tiles/dungeon_tile_17_raw_1780348425.png','{"S": {"x": 0.5, "y": 0.931640625, "scale": 1, "rot": 180}, "E": {"x": 0.931640625, "y": 0.5, "scale": 1, "rot": 270}}');
INSERT INTO dungeon_tiles VALUES(18,'dungeon','Magazyn','/images/tiles/dungeon_tile_18_1780333450.png','dark fantasy dungeon storage room, tall wooden shelves with barrels and crates, rotting supplies, sacks of grain, dungeon provisions area, dim torchlight, musty atmosphere, rats lurking in shadows, game art style','["N", "E"]','Wysokie regały pełne beczek i skrzyń. Zapach zgniłej mąki i kwaśnego wina. W jednej skrzyni coś się poruszyło.','[]','[]','[]',NULL,'[]',0,1,'2026-06-01 13:56:14','2026-06-01 17:04:21','/images/tiles/dungeon_tile_18_raw_1780333311.png','{}');
INSERT INTO dungeon_tiles VALUES(19,'dungeon','Komnata Władcy','/images/tiles/dungeon_tile_19_1780341111.png','BOSS. Massive chamber with high vaulted ceiling, walls lined with skulls, massive stone throne awaiting the dungeon lord, doors south, top view','["S"]','BOSS. Ogromna komnata z wysokim sklepieniem. Ściany wyłożone czaszkami. Na masywnym kamiennym tronie czeka Władca.','[]','[]','[]',NULL,'[]',1,1,'2026-06-01 13:56:14','2026-06-01 19:12:10','/images/tiles/dungeon_tile_19_raw_1780341111.png','{}');
